/// Form 4136 fuel tax credit for this sole-proprietor business
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
pub struct FederalFuelTaxCredit {
    /// Qualified fuel and use lines for this business
    pub fuels: FederalFuelLines,
    /// How the credited tax was handled in the expense records above
    pub expense_treatment: FederalFuelExpenseTreatment,
    /// Fuel purchase or issuer sale, payment of tax, equipment/use where applicable, and business records are complete
    /// Your fuel invoices and use records show this. No leaves this fuel tax credit out of the estimate with a notice.
    pub records_complete: bool,
}

// Answers and unknowns: what dropping the unconfirmed
// ultimate-purchaser fuel uses left out.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(crate) struct FuelUseDrop {
    // A No answer left a use out.
    pub(crate) left_out: bool,
}

impl FuelUseDrop {
    fn keep(&mut self, qualified: bool, others: bool) -> bool {
        if qualified && others {
            return true;
        }
        self.left_out = true;
        false
    }

    fn fuel(&mut self, slot: &mut Option<FederalFuelUse>) {
        if let Some(value) = slot
            && !self.keep(value.qualified, value.not_claimed_elsewhere)
        {
            *slot = None;
        }
    }

    fn alternative(&mut self, slot: &mut Option<FederalAlternativeFuelUse>) {
        if let Some(value) = slot
            && !self.keep(value.qualified, value.not_claimed_elsewhere)
        {
            *slot = None;
        }
    }

    // A group whose own answers do not hold leaves all its uses out.
    fn group<T>(&mut self, slot: &mut Option<T>, holds: impl Fn(&T) -> bool) {
        if slot.as_ref().is_some_and(|value| !holds(value)) {
            self.left_out = true;
            *slot = None;
        }
    }

    // A group emptied by this call goes too; one entered empty stays for
    // its validity check.
    fn emptied<T>(self, before: Self, slot: &mut Option<T>, has: impl Fn(&T) -> bool) {
        if self != before && slot.as_ref().is_some_and(|value| !has(value)) {
            *slot = None;
        }
    }
}

impl FederalFuelLines {
    /// Leaves out each ultimate-purchaser use whose answers do not qualify;
    /// the remaining lines are claimed. Vendor and card-issuer claims are
    /// `drop_unsupported`'s.
    pub(crate) fn drop_unconfirmed_uses(&mut self) -> FuelUseDrop {
        let mut drop = FuelUseDrop::default();
        if (self.diesel_intercity_local_bus.is_some()
            || self.kerosene_intercity_local_bus.is_some())
            && self.intercity_bus_no_waiver != Some(true)
        {
            drop.left_out = true;
            self.diesel_intercity_local_bus = None;
            self.kerosene_intercity_local_bus = None;
        }
        if self.has_export_use() && self.export_proof_complete != Some(true) {
            drop.left_out = true;
            for slot in [
                &mut self.gasoline_export,
                &mut self.aviation_gasoline_export,
                &mut self.diesel_export,
                &mut self.kerosene_export,
                &mut self.emulsion_export,
                &mut self.gasoline_blendstock_export,
                &mut self.dyed_diesel_export,
                &mut self.dyed_kerosene_export,
            ] {
                *slot = None;
            }
        }
        for slot in [
            &mut self.gasoline_off_highway,
            &mut self.gasoline_farm,
            &mut self.gasoline_commercial_fishing,
            &mut self.gasoline_school_bus,
            &mut self.gasoline_intercity_local_bus,
            &mut self.gasoline_export,
            &mut self.aviation_gasoline_commercial,
            &mut self.aviation_gasoline_nonpropulsion_off_highway,
            &mut self.aviation_gasoline_export,
            &mut self.diesel_off_highway,
            &mut self.diesel_farm,
            &mut self.diesel_trains,
            &mut self.diesel_intercity_local_bus,
            &mut self.diesel_export,
            &mut self.kerosene_off_highway,
            &mut self.kerosene_farm,
            &mut self.kerosene_intercity_local_bus,
            &mut self.kerosene_export,
            &mut self.kerosene_off_highway_taxed_044,
            &mut self.kerosene_off_highway_taxed_219,
            &mut self.p_series_off_highway,
            &mut self.hydrogen_off_highway,
            &mut self.fischer_tropsch_off_highway,
            &mut self.biomass_liquid_off_highway,
            &mut self.biomass_gas_off_highway,
            &mut self.emulsion_off_highway,
            &mut self.emulsion_farm,
            &mut self.emulsion_intercity_local_bus,
            &mut self.emulsion_export,
            &mut self.gasoline_blendstock_export,
            &mut self.dyed_diesel_export,
            &mut self.dyed_kerosene_export,
        ] {
            drop.fuel(slot);
        }
        for slot in
            [&mut self.lpg_off_highway, &mut self.cng_off_highway, &mut self.lng_off_highway]
        {
            drop.alternative(slot);
        }
        drop.group(&mut self.emulsion_blender, |claim| {
            claim.statement_facts_confirmed && claim.not_claimed_elsewhere
        });
        drop.group(&mut self.aviation_commercial, |claim| claim.no_waiver);
        let before = drop;
        if let Some(claim) = &mut self.aviation_commercial {
            drop.fuel(&mut claim.taxed_at_244);
            drop.fuel(&mut claim.taxed_at_219);
        }
        drop.emptied(before, &mut self.aviation_commercial, |claim| {
            claim.uses().iter().any(Option::is_some)
        });
        drop.group(&mut self.aviation_kerosene_foreign_trade, |claim| claim.no_waiver);
        let before = drop;
        if let Some(claim) = &mut self.aviation_kerosene_foreign_trade {
            drop.fuel(&mut claim.taxed_at_244);
            drop.fuel(&mut claim.taxed_at_219);
        }
        drop.emptied(before, &mut self.aviation_kerosene_foreign_trade, |claim| {
            claim.uses().iter().any(Option::is_some)
        });
        drop.group(&mut self.aviation_kerosene_farm, |claim| {
            claim.applicator_was_ultimate_purchaser && claim.no_waiver && claim.distinct_gallons
        });
        let before = drop;
        if let Some(claim) = &mut self.aviation_kerosene_farm {
            drop.fuel(&mut claim.taxed_at_244_application);
            drop.fuel(&mut claim.taxed_at_244_direct_flight);
            drop.fuel(&mut claim.taxed_at_219_application);
            drop.fuel(&mut claim.taxed_at_219_direct_flight);
        }
        drop.emptied(before, &mut self.aviation_kerosene_farm, |claim| {
            claim.uses().iter().any(Option::is_some)
        });
        drop.group(&mut self.aviation_gasoline_farm, |claim| {
            claim.applicator_was_ultimate_purchaser && claim.distinct_gallons
        });
        let before = drop;
        if let Some(claim) = &mut self.aviation_gasoline_farm {
            drop.fuel(&mut claim.aerial_application);
            drop.fuel(&mut claim.direct_airfield_farm_flight);
        }
        drop.emptied(before, &mut self.aviation_gasoline_farm, |claim| {
            claim.uses().iter().any(Option::is_some)
        });
        drop.group(&mut self.aviation_gasoline_type_10, |uses| uses.distinct_gallons);
        let before = drop;
        if let Some(uses) = &mut self.aviation_gasoline_type_10 {
            if uses.mineral_and_tree_airport_condition != Some(true) {
                for slot in [
                    &mut uses.helicopter_mineral_transport,
                    &mut uses.helicopter_tree_work,
                    &mut uses.fixed_wing_tree_work,
                ] {
                    if slot.take().is_some() {
                        drop.left_out = true;
                    }
                }
            }
            if uses.fixed_wing_acute_care_condition != Some(true)
                && uses.fixed_wing_emergency_medical.take().is_some()
            {
                drop.left_out = true;
            }
            drop.fuel(&mut uses.helicopter_mineral_transport);
            drop.fuel(&mut uses.helicopter_tree_work);
            drop.fuel(&mut uses.helicopter_emergency_medical);
            drop.fuel(&mut uses.fixed_wing_tree_work);
            drop.fuel(&mut uses.fixed_wing_emergency_medical);
        }
        drop.emptied(before, &mut self.aviation_gasoline_type_10, |uses| {
            uses.uses().iter().any(Option::is_some)
        });
        if let Some(trade) = &self.aviation_gasoline_foreign_trade {
            let reciprocity = match trade.registration {
                FederalForeignTradeAircraftRegistration::UnitedStates => true,
                FederalForeignTradeAircraftRegistration::Foreign { reciprocal_privileges } => {
                    reciprocal_privileges
                }
            };
            let fuel = drop.keep(trade.fuel.qualified, trade.fuel.not_claimed_elsewhere);
            let facts = trade.qualifying_civil_aircraft_trade && trade.distinct_gallons;
            if !fuel || !facts || !drop.keep(reciprocity, true) {
                if !facts {
                    drop.left_out = true;
                }
                self.aviation_gasoline_foreign_trade = None;
            }
        }
        let before = drop;
        if let Some(bus) = &mut self.bus_uses {
            if bus.has_local_bus_use() {
                let qualified = bus.local_bus_qualified.unwrap_or(false);
                if !drop.keep(qualified, true) {
                    bus.diesel_local_bus = None;
                    bus.kerosene_local_bus = None;
                    bus.emulsion_local_bus = None;
                    bus.lpg_local_bus = None;
                    bus.p_series_local_bus = None;
                    bus.cng_local_bus = None;
                    bus.hydrogen_local_bus = None;
                    bus.fischer_tropsch_local_bus = None;
                    bus.biomass_liquid_local_bus = None;
                    bus.lng_local_bus = None;
                    bus.biomass_gas_local_bus = None;
                }
            }
            for slot in [
                &mut bus.diesel_school_bus,
                &mut bus.kerosene_school_bus,
                &mut bus.emulsion_school_bus,
                &mut bus.p_series_public_bus,
                &mut bus.hydrogen_public_bus,
                &mut bus.fischer_tropsch_public_bus,
                &mut bus.biomass_liquid_public_bus,
                &mut bus.biomass_gas_public_bus,
                &mut bus.diesel_local_bus,
                &mut bus.kerosene_local_bus,
                &mut bus.emulsion_local_bus,
                &mut bus.p_series_local_bus,
                &mut bus.hydrogen_local_bus,
                &mut bus.fischer_tropsch_local_bus,
                &mut bus.biomass_liquid_local_bus,
                &mut bus.biomass_gas_local_bus,
            ] {
                drop.fuel(slot);
            }
            for slot in [
                &mut bus.lpg_public_bus,
                &mut bus.cng_public_bus,
                &mut bus.lng_public_bus,
                &mut bus.lpg_local_bus,
                &mut bus.cng_local_bus,
                &mut bus.lng_local_bus,
            ] {
                drop.alternative(slot);
            }
        }
        drop.emptied(before, &mut self.bus_uses, |bus| {
            bus.priced_uses().iter().any(|(value, _)| value.is_some())
                || bus.alternative_uses().iter().any(|(value, _, _)| value.is_some())
        });
        let before = drop;
        if let Some(other) = &mut self.other_uses {
            drop.fuel(&mut other.diesel_type_8);
            drop.fuel(&mut other.kerosene_type_8);
            drop.fuel(&mut other.emulsion_type_8);
        }
        drop.emptied(before, &mut self.other_uses, |other| {
            other.priced_uses().iter().any(|(value, _)| value.is_some())
        });
        drop
    }
}

const FUEL_LINE_COUNT: usize = 52;
const VENDOR_STATE_DIESEL_RATE: i64 = 243;
const VENDOR_STATE_KEROSENE_RATE: i64 = 243;
const FUEL_LINE_NAMES: [&str; FUEL_LINE_COUNT] = [
    "1a", "1b", "1c", "1d", "2a", "2b", "2c", "2d", "3a", "3b", "3c", "3d", "3e", "4a", "4b", "4c",
    "4d", "4e", "4f", "5a", "5b", "5c", "5d", "5e", "6a", "6b", "7a", "7b", "7c", "8a", "8b", "8c",
    "8d", "8e", "8f", "11a", "11b", "11c", "11d", "11e", "11f", "11g", "11h", "13a", "13b",
    "13c_219", "13c_244", "14a", "14b", "15a", "16a", "16b",
];

impl FederalFuelLines {
    fn line_cents(value: Option<&FederalFuelUse>, rate_thousandths: i64) -> i64 {
        value.map_or(0, |v| {
            crate::kernel::ratio::fraction(
                i64::from(v.thousandths_of_gallon),
                rate_thousandths,
                10_000,
            )
        })
    }

    fn line_2b_gallons_thousandths(&self) -> i64 {
        self.aviation_gasoline_nonpropulsion_off_highway
            .as_ref()
            .map_or(0, |value| i64::from(value.thousandths_of_gallon))
            + self
                .aviation_gasoline_farm
                .as_ref()
                .map_or(0, FederalAviationGasolineFarmUse::gallons_thousandths)
            + self
                .aviation_gasoline_type_10
                .as_ref()
                .map_or(0, FederalAviationGasolineType10Uses::gallons_thousandths)
            + self
                .aviation_gasoline_foreign_trade
                .as_ref()
                .map_or(0, |value| i64::from(value.fuel.thousandths_of_gallon))
    }

    fn line_2b_cents(&self) -> i64 {
        crate::kernel::ratio::fraction(self.line_2b_gallons_thousandths(), 193, 10_000)
    }

    fn line_2b_cost_cents(&self) -> i64 {
        self.aviation_gasoline_nonpropulsion_off_highway
            .as_ref()
            .map_or(0, |value| value.actual_cost)
            + self
                .aviation_gasoline_farm
                .as_ref()
                .map_or(0, FederalAviationGasolineFarmUse::cost_cents)
            + self.aviation_gasoline_type_10.as_ref().map_or(0, |type_10| {
                type_10.uses().into_iter().flatten().map(|value| value.actual_cost).sum()
            })
            + self
                .aviation_gasoline_foreign_trade
                .as_ref()
                .map_or(0, |value| value.fuel.actual_cost)
    }

    fn line_5c_or_5d_gallons_thousandths(&self, original_rate: i64) -> i64 {
        let trade = self.aviation_kerosene_foreign_trade.as_ref().map_or(0, |value| {
            let fuel = if original_rate == 244 { &value.taxed_at_244 } else { &value.taxed_at_219 };
            fuel.as_ref().map_or(0, |fuel| i64::from(fuel.thousandths_of_gallon))
        });
        trade
            + self
                .aviation_kerosene_farm
                .as_ref()
                .map_or(0, |value| value.gallons_thousandths(original_rate))
    }

    fn line_5c_or_5d_cents(&self, original_rate: i64) -> i64 {
        let credit_rate = if original_rate == 244 { 243 } else { 218 };
        crate::kernel::ratio::fraction(
            self.line_5c_or_5d_gallons_thousandths(original_rate),
            credit_rate,
            10_000,
        )
    }

    fn line_5c_through_5e_cost_cents(&self) -> i64 {
        self.aviation_kerosene_foreign_trade.as_ref().map_or(0, |value| {
            value.uses().into_iter().flatten().map(|fuel| fuel.actual_cost).sum::<i64>()
        }) + self.aviation_kerosene_farm.as_ref().map_or(0, FederalFarmAviationKerosene::cost_cents)
    }

    fn priced_uses(&self) -> [(Option<&FederalFuelUse>, i64); 33] {
        [
            (self.gasoline_off_highway.as_ref(), 183),
            (self.gasoline_farm.as_ref(), 183),
            (self.gasoline_commercial_fishing.as_ref(), 183),
            (self.gasoline_school_bus.as_ref(), 183),
            (self.aviation_gasoline_commercial.as_ref(), 150),
            (self.aviation_gasoline_nonpropulsion_off_highway.as_ref(), 193),
            (self.diesel_off_highway.as_ref(), 243),
            (self.diesel_farm.as_ref(), 243),
            (self.diesel_trains.as_ref(), 243),
            (self.kerosene_off_highway.as_ref(), 243),
            (self.kerosene_farm.as_ref(), 243),
            (self.kerosene_off_highway_taxed_044.as_ref(), 43),
            (self.kerosene_off_highway_taxed_219.as_ref(), 218),
            (self.p_series_off_highway.as_ref(), 183),
            (self.hydrogen_off_highway.as_ref(), 183),
            (self.fischer_tropsch_off_highway.as_ref(), 243),
            (self.biomass_liquid_off_highway.as_ref(), 243),
            (self.biomass_gas_off_highway.as_ref(), 183),
            (self.emulsion_off_highway.as_ref(), 197),
            (self.gasoline_intercity_local_bus.as_ref(), 183),
            (self.diesel_intercity_local_bus.as_ref(), 170),
            (self.kerosene_intercity_local_bus.as_ref(), 170),
            (self.gasoline_export.as_ref(), 184),
            (self.aviation_gasoline_export.as_ref(), 194),
            (self.diesel_export.as_ref(), 244),
            (self.kerosene_export.as_ref(), 244),
            (self.emulsion_export.as_ref(), 198),
            (self.emulsion_farm.as_ref(), 197),
            (self.emulsion_intercity_local_bus.as_ref(), 124),
            (self.gasoline_blendstock_export.as_ref(), 1),
            (self.dyed_diesel_export.as_ref(), 1),
            (self.dyed_kerosene_export.as_ref(), 1),
            (self.aviation_gasoline_foreign_trade.as_ref().map(|value| &value.fuel), 194),
        ]
    }

    fn regular_lines(&self) -> [i64; 18] {
        let amount = self.priced_uses().map(|(use_line, rate)| Self::line_cents(use_line, rate));
        [
            amount[0],
            amount[1],
            amount[2] + amount[3] + amount[19],
            amount[4],
            self.line_2b_cents(),
            amount[6],
            amount[7],
            amount[8],
            amount[9],
            amount[10],
            amount[11],
            amount[12],
            amount[13],
            amount[14],
            amount[15],
            amount[16],
            amount[17],
            amount[18] + amount[27] + amount[28],
        ]
    }

    fn line_16a_cents(&self) -> i64 {
        let gallons = [self.gasoline_blendstock_export.as_ref(), self.dyed_diesel_export.as_ref()]
            .into_iter()
            .flatten()
            .map(|value| i64::from(value.thousandths_of_gallon))
            .sum::<i64>();
        crate::kernel::ratio::fraction(gallons, 1, 10_000)
    }

    pub(crate) fn lines(&self) -> [i64; FUEL_LINE_COUNT] {
        let regular = self.regular_lines();
        let aviation = self
            .aviation_commercial
            .as_ref()
            .map_or([0, 0], FederalCommercialAviationKerosene::lines);
        let foreign_trade = self
            .aviation_kerosene_foreign_trade
            .as_ref()
            .map_or([0, 0, 0], FederalForeignTradeAviationKerosene::lines);
        let vendor_aviation = self
            .vendor_aviation_kerosene
            .as_ref()
            .map_or([0, 0], crate::FederalVendorAviationClaim::lines);
        let vendor_nontaxable = self
            .vendor_aviation_nontaxable
            .as_ref()
            .map_or([0; 3], crate::FederalVendorNontaxableAviationClaim::lines);
        let card_issuer =
            self.card_issuer.as_ref().map_or([0; 4], crate::FederalCardIssuerClaim::lines);
        let mut lines = [
            regular[0],
            regular[1],
            regular[2],
            Self::line_cents(self.gasoline_export.as_ref(), 184),
            regular[3],
            regular[4],
            Self::line_cents(self.aviation_gasoline_export.as_ref(), 194),
            Self::line_cents(
                self.aviation_gasoline_foreign_trade.as_ref().map(|value| &value.fuel),
                1,
            ),
            regular[5],
            regular[6],
            regular[7],
            Self::line_cents(self.diesel_intercity_local_bus.as_ref(), 170),
            Self::line_cents(self.diesel_export.as_ref(), 244),
            regular[8],
            regular[9],
            Self::line_cents(self.kerosene_intercity_local_bus.as_ref(), 170),
            Self::line_cents(self.kerosene_export.as_ref(), 244),
            regular[10],
            regular[11],
            aviation[0],
            aviation[1],
            self.line_5c_or_5d_cents(244),
            self.line_5c_or_5d_cents(219),
            foreign_trade[2],
            self.vendor_state_diesel
                .as_ref()
                .map_or(0, |claim| claim.line_cents(VENDOR_STATE_DIESEL_RATE)),
            self.vendor_bus_diesel.as_ref().map_or(0, crate::FederalVendorBusClaim::line_cents),
            self.vendor_state_kerosene
                .as_ref()
                .map_or(0, |claim| claim.line_cents(VENDOR_STATE_KEROSENE_RATE)),
            self.vendor_blocked_pump_kerosene
                .as_ref()
                .map_or(0, crate::FederalBlockedPumpKeroseneClaim::line_cents),
            self.vendor_bus_kerosene.as_ref().map_or(0, crate::FederalVendorBusClaim::line_cents),
            vendor_aviation[0],
            vendor_aviation[1],
            self.vendor_aviation_noncommercial
                .as_ref()
                .map_or(0, crate::FederalVendorNoncommercialAviationClaim::line_cents),
            vendor_nontaxable[0],
            vendor_nontaxable[1],
            vendor_nontaxable[2],
            self.lpg_off_highway
                .as_ref()
                .and_then(|v| v.line_cents(AlternativeFuelKind::Lpg, 183))
                .unwrap_or(0),
            regular[12],
            self.cng_off_highway
                .as_ref()
                .and_then(|v| v.line_cents(AlternativeFuelKind::Cng, 183))
                .unwrap_or(0),
            regular[13],
            regular[14],
            regular[15],
            self.lng_off_highway
                .as_ref()
                .and_then(|v| v.line_cents(AlternativeFuelKind::Lng, 243))
                .unwrap_or(0),
            regular[16],
            card_issuer[0],
            card_issuer[1],
            card_issuer[2],
            card_issuer[3],
            regular[17],
            Self::line_cents(self.emulsion_export.as_ref(), 198),
            self.emulsion_blender.as_ref().map_or(0, FederalEmulsionBlenderClaim::credit_cents),
            self.line_16a_cents(),
            Self::line_cents(self.dyed_kerosene_export.as_ref(), 1),
        ];
        if let Some(bus) = &self.bus_uses {
            let additional = bus.lines();
            for (index, amount) in [
                8, 13, 35, 36, 37, 38, 39, 40, 41, 42, 47, 8, 13, 47, 35, 36, 37, 38, 39, 40, 41,
                42,
            ]
            .into_iter()
            .zip(additional)
            {
                lines[index] += amount;
            }
        }
        if let Some(other) = &self.other_uses {
            let [diesel, kerosene, emulsion] = other.lines();
            lines[8] += diesel;
            lines[13] += kerosene;
            lines[47] += emulsion;
        }
        lines
    }

    pub(crate) fn labeled_lines(&self) -> impl Iterator<Item = (&'static str, i64)> {
        FUEL_LINE_NAMES.into_iter().zip(self.lines())
    }

    pub(crate) fn credit_cents(&self) -> i64 {
        self.lines().iter().sum()
    }

    pub(crate) fn uses(&self) -> [Option<&FederalFuelUse>; 33] {
        self.priced_uses().map(|(use_line, _)| use_line)
    }

    pub(crate) fn alternative_uses(&self) -> [Option<&FederalAlternativeFuelUse>; 3] {
        [
            self.lpg_off_highway.as_ref(),
            self.cng_off_highway.as_ref(),
            self.lng_off_highway.as_ref(),
        ]
    }

    pub(crate) fn qualified(&self) -> bool {
        self.uses().iter().flatten().all(|v| v.qualified && v.not_claimed_elsewhere)
            && self
                .alternative_uses()
                .iter()
                .flatten()
                .all(|v| v.qualified && v.not_claimed_elsewhere)
            && self
                .aviation_commercial
                .as_ref()
                .is_none_or(FederalCommercialAviationKerosene::qualified)
            && self
                .aviation_kerosene_foreign_trade
                .as_ref()
                .is_none_or(FederalForeignTradeAviationKerosene::qualified)
            && self
                .aviation_kerosene_farm
                .as_ref()
                .is_none_or(FederalFarmAviationKerosene::qualified)
            && self
                .aviation_gasoline_farm
                .as_ref()
                .is_none_or(FederalAviationGasolineFarmUse::qualified)
            && self
                .aviation_gasoline_type_10
                .as_ref()
                .is_none_or(FederalAviationGasolineType10Uses::qualified)
            && self
                .aviation_gasoline_foreign_trade
                .as_ref()
                .is_none_or(FederalAviationGasolineForeignTrade::qualified)
            && self.bus_uses.as_ref().is_none_or(FederalBusFuelUses::qualified)
            && self.other_uses.as_ref().is_none_or(FederalOtherFuelUses::qualified)
            && self.emulsion_blender.as_ref().is_none_or(FederalEmulsionBlenderClaim::qualified)
            && self
                .vendor_state_diesel
                .as_ref()
                .is_none_or(crate::FederalVendorStateClaim::qualified)
            && self.vendor_bus_diesel.as_ref().is_none_or(crate::FederalVendorBusClaim::qualified)
            && self
                .vendor_state_kerosene
                .as_ref()
                .is_none_or(crate::FederalVendorStateClaim::qualified)
            && self
                .vendor_blocked_pump_kerosene
                .as_ref()
                .is_none_or(crate::FederalBlockedPumpKeroseneClaim::qualified)
            && self.vendor_bus_kerosene.as_ref().is_none_or(crate::FederalVendorBusClaim::qualified)
            && self
                .vendor_aviation_kerosene
                .as_ref()
                .is_none_or(crate::FederalVendorAviationClaim::qualified)
            && self
                .vendor_aviation_noncommercial
                .as_ref()
                .is_none_or(crate::FederalVendorNoncommercialAviationClaim::qualified)
            && self
                .vendor_aviation_nontaxable
                .as_ref()
                .is_none_or(crate::FederalVendorNontaxableAviationClaim::qualified)
            && self.card_issuer.as_ref().is_none_or(crate::FederalCardIssuerClaim::qualified)
            && ((self.diesel_intercity_local_bus.is_none()
                && self.kerosene_intercity_local_bus.is_none())
                || self.intercity_bus_no_waiver == Some(true))
            && (!self.has_export_use() || self.export_proof_complete == Some(true))
    }

    pub(crate) fn has_farm_operator_use(&self) -> bool {
        self.gasoline_farm.is_some()
            || self.diesel_farm.is_some()
            || self.kerosene_farm.is_some()
            || self.emulsion_farm.is_some()
    }

    fn has_export_use(&self) -> bool {
        self.gasoline_export.is_some()
            || self.aviation_gasoline_export.is_some()
            || self.diesel_export.is_some()
            || self.kerosene_export.is_some()
            || self.emulsion_export.is_some()
            || self.gasoline_blendstock_export.is_some()
            || self.dyed_diesel_export.is_some()
            || self.dyed_kerosene_export.is_some()
    }

    pub(crate) fn valid(&self) -> bool {
        let uses = self.uses();
        (uses.iter().any(Option::is_some)
            || self.alternative_uses().iter().any(Option::is_some)
            || self.aviation_commercial.is_some()
            || self.aviation_kerosene_foreign_trade.is_some()
            || self.aviation_kerosene_farm.is_some()
            || self.aviation_gasoline_farm.is_some()
            || self.aviation_gasoline_type_10.is_some()
            || self.bus_uses.is_some()
            || self.other_uses.is_some()
            || self.emulsion_blender.is_some()
            || self.vendor_state_diesel.is_some()
            || self.vendor_bus_diesel.is_some()
            || self.vendor_state_kerosene.is_some()
            || self.vendor_blocked_pump_kerosene.is_some()
            || self.vendor_bus_kerosene.is_some()
            || self.vendor_aviation_kerosene.is_some()
            || self.vendor_aviation_noncommercial.is_some()
            || self.vendor_aviation_nontaxable.is_some()
            || self.card_issuer.is_some())
            && uses.iter().flatten().all(|v| {
                (1..=2_000_000_000).contains(&v.thousandths_of_gallon)
                    && (0..=100_000_000_000).contains(&v.actual_cost)
            })
            && self.priced_uses().into_iter().all(|(use_line, rate)| {
                use_line.is_none_or(|v| v.actual_cost >= Self::line_cents(use_line, rate))
            })
            && self.line_2b_cost_cents() >= self.line_2b_cents()
            && self.line_5c_through_5e_cost_cents()
                >= self.line_5c_or_5d_cents(244)
                    + self.line_5c_or_5d_cents(219)
                    + self
                        .aviation_kerosene_foreign_trade
                        .as_ref()
                        .map_or(0, |value| value.lines()[2])
            && self.lpg_off_highway.as_ref().is_none_or(|v| v.valid(AlternativeFuelKind::Lpg, 183))
            && self.cng_off_highway.as_ref().is_none_or(|v| v.valid(AlternativeFuelKind::Cng, 183))
            && self.lng_off_highway.as_ref().is_none_or(|v| v.valid(AlternativeFuelKind::Lng, 243))
            && self
                .aviation_commercial
                .as_ref()
                .is_none_or(FederalCommercialAviationKerosene::valid)
            && self
                .aviation_kerosene_foreign_trade
                .as_ref()
                .is_none_or(FederalForeignTradeAviationKerosene::valid)
            && self.aviation_kerosene_farm.as_ref().is_none_or(FederalFarmAviationKerosene::valid)
            && self
                .aviation_gasoline_farm
                .as_ref()
                .is_none_or(FederalAviationGasolineFarmUse::valid)
            && self
                .aviation_gasoline_type_10
                .as_ref()
                .is_none_or(FederalAviationGasolineType10Uses::valid)
            && self
                .aviation_gasoline_foreign_trade
                .as_ref()
                .is_none_or(FederalAviationGasolineForeignTrade::valid)
            && self.bus_uses.as_ref().is_none_or(FederalBusFuelUses::valid)
            && self.other_uses.as_ref().is_none_or(FederalOtherFuelUses::valid)
            && self.emulsion_blender.as_ref().is_none_or(FederalEmulsionBlenderClaim::valid)
            && self
                .vendor_state_diesel
                .as_ref()
                .is_none_or(|claim| claim.valid(VENDOR_STATE_DIESEL_RATE))
            && self.vendor_bus_diesel.as_ref().is_none_or(crate::FederalVendorBusClaim::valid)
            && self
                .vendor_state_kerosene
                .as_ref()
                .is_none_or(|claim| claim.valid(VENDOR_STATE_KEROSENE_RATE))
            && self
                .vendor_blocked_pump_kerosene
                .as_ref()
                .is_none_or(crate::FederalBlockedPumpKeroseneClaim::valid)
            && self.vendor_bus_kerosene.as_ref().is_none_or(crate::FederalVendorBusClaim::valid)
            && self
                .vendor_aviation_kerosene
                .as_ref()
                .is_none_or(crate::FederalVendorAviationClaim::valid)
            && self
                .vendor_aviation_noncommercial
                .as_ref()
                .is_none_or(crate::FederalVendorNoncommercialAviationClaim::valid)
            && self
                .vendor_aviation_nontaxable
                .as_ref()
                .is_none_or(crate::FederalVendorNontaxableAviationClaim::valid)
            && self.card_issuer.as_ref().is_none_or(crate::FederalCardIssuerClaim::valid)
            && self.aviation_vendor_sale_references_unique()
    }

    fn aviation_vendor_sale_references_unique(&self) -> bool {
        let mut references = BTreeSet::new();
        self.vendor_aviation_kerosene
            .iter()
            .flat_map(|claim| claim.sales.iter().map(|sale| sale.sale_reference.trim()))
            .chain(
                self.vendor_aviation_noncommercial
                    .iter()
                    .flat_map(|claim| claim.sales.iter().map(|sale| sale.sale_reference.trim())),
            )
            .chain(
                self.vendor_aviation_nontaxable
                    .iter()
                    .flat_map(|claim| claim.sales.iter().map(|sale| sale.sale_reference.trim())),
            )
            .chain(
                self.card_issuer
                    .iter()
                    .flat_map(|claim| claim.sales.iter().map(|sale| sale.sale_reference.trim())),
            )
            .all(|reference| references.insert(reference))
    }
}

impl FederalFuelTaxCredit {
    pub(crate) fn lines(&self) -> [i64; FUEL_LINE_COUNT] {
        self.fuels.lines()
    }

    pub(crate) fn labeled_lines(&self) -> impl Iterator<Item = (&'static str, i64)> {
        FUEL_LINE_NAMES.into_iter().zip(self.lines())
    }

    pub(crate) fn credit_cents(&self) -> i64 {
        self.fuels.credit_cents()
    }

    pub(crate) fn expense_recovery_cents(&self) -> i64 {
        // The issuer's credit is never a fuel-cost deduction recovery here.
        // Retained accrual issuer income has its own once-only path in receipts().
        self.credit_cents()
            - self.fuels.card_issuer.as_ref().map_or(0, |claim| claim.lines().iter().sum::<i64>())
    }

    pub(crate) fn valid(&self) -> bool {
        self.fuels.valid()
    }
}
impl FederalBusinessExpense {
    pub(crate) fn total(expenses: &[Self]) -> i64 {
        let mut costs = [0; 3];
        for e in expenses {
            match e.treatment {
                BusinessExpenseKind::Ordinary | BusinessExpenseKind::DeMinimis { .. } => {
                    costs[0] += e.amount
                }
                BusinessExpenseKind::Meals => costs[1] += e.amount,
                BusinessExpenseKind::TransportationMeals => costs[2] += e.amount,
                BusinessExpenseKind::Nondeductible => {}
            }
        }
        costs[0]
            + crate::kernel::ratio::fraction(costs[1], 50, 100)
            + crate::kernel::ratio::fraction(costs[2], 80, 100)
    }
    // Same per-item ordinary/meals/DOT/nondeductible treatment as `total` above,
    // applied per item so it can be grouped by printed line without changing `total`'s
    // own grouped-then-rounded result.
    fn contribution(&self) -> i64 {
        match self.treatment {
            BusinessExpenseKind::Ordinary | BusinessExpenseKind::DeMinimis { .. } => self.amount,
            BusinessExpenseKind::Meals => crate::kernel::ratio::fraction(self.amount, 50, 100),
            BusinessExpenseKind::TransportationMeals => {
                crate::kernel::ratio::fraction(self.amount, 80, 100)
            }
            BusinessExpenseKind::Nondeductible => 0,
        }
    }
    // One total per Schedule C Part II printed line, in `BusinessExpenseCategory::LINES` order.
    pub(crate) fn category_totals(expenses: &[Self]) -> [i64; BusinessExpenseCategory::COUNT] {
        let mut totals = [0; BusinessExpenseCategory::COUNT];
        for e in expenses {
            totals[e.category.index()] += e.contribution();
        }
        totals
    }
}

/// Schedule C accounting method
#[derive(
    Clone, Copy, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport,
)]
pub enum BusinessAccounting {
    /// Cash method
    Cash,
    /// Accrual method
    Accrual,
}

/// Business activity
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
// Business activities, like income documents, own their complete schema payload inline.
#[allow(clippy::large_enum_variant)]
pub enum BusinessActivity {
    /// Ordinary trade or business — Schedule C
    Ordinary {
        /// Returns and allowances (Schedule C line 2)
        #[libertas_money("USD", 2)]
        #[libertas_number(min = 0)]
        #[libertas_default(0)]
        returns: i64,
        /// Gross receipts under your accounting method, including reported 1099 income once
        #[libertas_money("USD", 2)]
        #[libertas_number(min = 0)]
        receipts: i64,
        /// Established accounting method for this Schedule C activity
        accounting: BusinessAccounting,
    },
    /// Farming — Schedule F
    Farming { data: crate::FarmIncome },
    /// Professional gambling
    Gambling {
        /// Returns and allowances (Schedule C line 2)
        #[libertas_money("USD", 2)]
        #[libertas_number(min = 0)]
        #[libertas_default(0)]
        returns: i64,
        /// Gross winning receipts, before losing wagers and expenses
        #[libertas_money("USD", 2)]
        #[libertas_number(min = 0)]
        receipts: i64,
        /// Accounting method for this Schedule C activity
        accounting: BusinessAccounting,
        /// Documented wagering losses before the 2026 limit
        /// Do not include losing wagers again in Business expenses or net them against gross winning receipts.
        #[libertas_money("USD", 2)]
        #[libertas_number(min = 0)]
        losses: i64,
        /// Federal W-2G withholding on winnings included in receipts
        #[libertas_money("USD", 2)]
        #[libertas_number(min = 0)]
        withholding: i64,
        /// Regular profit-seeking gambling business and complete reconciled records
        /// Receipts contain only winning amounts for this activity. Confirm professional status and no unresolved wager/session or prize treatment. Enter ordinary related business costs separately; the App applies their normal limits before the wagering limit. Professional status depends on whether you gamble regularly and continuously to make a profit (your records, hours and history); Yes or No is required. No leaves this business out of the estimate with a notice: enter casual gambling on the gambling page instead.
        eligible: bool,
    },
}
impl BusinessActivity {
    pub(crate) fn valid(&self) -> bool {
        match self {
            Self::Ordinary { receipts, returns, .. } => {
                [*receipts, *returns].iter().all(|amount| (0..=100000000000).contains(amount))
            }
            Self::Farming { data } => data.valid(),
            Self::Gambling { receipts, returns, losses, withholding, .. } => {
                (0..=*receipts).contains(returns)
                    && [*receipts, *losses, *withholding]
                        .iter()
                        .all(|v| (0..=100000000000).contains(v))
            }
        }
    }
    pub(crate) fn receipts(&self) -> i64 {
        match self {
            Self::Ordinary { receipts, returns, .. } | Self::Gambling { receipts, returns, .. } => {
                receipts - returns
            }
            Self::Farming { data } => data.gross(),
        }
    }
}

/// Business source and U.S. connection
/// For services, use where the work was performed, not the customer, bank or payer address. Mixed operations and exceptional U.S. connections need their own allocation.
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
pub enum BusinessSource {
    /// In the United States
    /// All entered business income and deductions are connected with conducting this business in the United States.
    UnitedStates,
    /// Services performed wholly in a foreign country
    ForeignServices {
        /// Covered by the foreign social security system under a totalization agreement
        /// You have, or will attach, its certificate of coverage. No U.S. self-employment tax applies to this business.
        totalization_exempt: bool,
        /// Ordinary foreign service business confirmed
        /// All services were performed outside the United States and its territories by you; capital such as inventory, equipment or property is not a material income-producing factor; this income has no effective connection to a U.S. business. No foreign business tax credit or deduction, currency adjustment, treaty benefit or special foreign treatment is requested. Receipts and expenses are recorded in U.S. dollars. Your travel and work calendar shows where services were performed. No leaves this business out of the estimate with a notice; that situation is not supported.
        confirmed: bool,
    },
}

/// Qualified tips received in this sole-proprietor business
/// Enter only tips separately reported to you on a 2026 information return. Include them in this business's Schedule C ordinary receipts or Schedule F other farm operating receipts once; this record claims a deduction, not more income.
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
pub struct FederalBusinessTips {
    /// Qualified cash tips already included in this business's ordinary or other farm receipts
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub amount: i64,
    /// Occupation, voluntary-tip rules and separate information-return reporting are confirmed
    /// The tips were paid by customers for an IRS-listed occupation, not by this business or its owner; they meet the applicable 2026 specified-service rule. No claims no qualified-tips deduction for this business, with a note.
    /// Check the payment statements and records identifying qualified tips.
    pub eligible: bool,
}

/// Qualified FLSA overtime separately reported on a 2026 Form 1099
/// This applies only when the worker is covered by the FLSA overtime requirement but the payer reports the compensation on Form 1099-NEC or Form 1099-MISC for federal income-tax purposes. The premium is already part of this business's ordinary receipts.
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
pub struct FederalBusinessOvertime {
    /// FLSA-required premium above the regular pay rate included in ordinary receipts
    /// Use only the amount separately reported in 2026 Form 1099-NEC box 1d or Form 1099-MISC box 14. Exclude the regular rate and voluntary or state-only overtime premiums.
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub amount: i64,
    /// FLSA coverage, required premium, 1099 reporting and no duplicate W-2 claim confirmed
    /// The same compensation is included in this business's receipts once. No claims no qualified-overtime deduction for this business, with a note.
    /// Check the payment statements and records identifying qualified overtime.
    pub eligible: bool,
}

/// Sole-proprietor business
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
pub struct FederalBusiness {
    /// Principal business or profession, including product or service
    /// Schedule C line A, for example "appraisal of real estate for lending institutions". Needed only for a printed return.
    #[libertas_default("")]
    pub principal_business: String,
    /// Business code
    /// Schedule C line B: the six-digit principal business or professional activity code from the Schedule C instructions, or 999999 when none fits. Leave empty until the return is printed.
    /// [NullText]
    /// Business code will be supplied when printing the return
    /// [SetText]
    /// The business activity code is
    // Legal tax classification: the business activity code is six digits.
    #[libertas_number(min = 100000, max = 999999)]
    #[libertas_default($null)]
    pub business_code: Option<u32>,
    /// Employer identification number
    /// Schedule C line D: the EIN issued to this business on Form SS-4, as 12-3456789; never your Social Security number. Leave empty when the business has none. Schedule 1-A prints it beside this business's qualified tips and overtime.
    // An EIN has nine digits, optionally separated by its hyphen.
    #[libertas_size(min = 0, max = 10)]
    #[libertas_default("")]
    #[libertas_pattern(r"([0-9]{2}-[0-9]{7})?")]
    pub ein: String,
    /// Business address
    /// Schedule C line E, street address, city, state and ZIP code. Leave empty when you run the business from the home at the address on your return.
    #[libertas_default("")]
    pub address: String,
    /// Started, acquired, reopened or restarted this business in 2026
    /// Schedule C line H: also Yes when you reopened it after a temporary closing and filed no 2025 Schedule C for it.
    #[libertas_default(false)]
    pub started_current_year: bool,
    /// Forms 1099 you had to file for 2026 payments
    /// Schedule C lines I and J. For 2026 a Form 1099 is required for payments of $2,000 or more to a nonemployee, and for rents, interest, royalties and other payments the Instructions for Forms 1099-MISC and 1099-NEC list.
    #[libertas_default(NoneRequired)]
    pub information_returns: InformationReturnFiling,
    /// Other business income (Schedule C line 6)
    pub other_income: Vec<crate::OtherBusinessIncome>,
    /// De minimis safe-harbor election
    #[libertas_default($null)]
    pub de_minimis: Option<crate::DeMinimisElection>,
    /// Leased vehicles deducted using actual expenses
    pub leased_vehicles: Vec<crate::BusinessLeasedVehicle>,
    /// Depletion of a working interest
    #[libertas_default($null)]
    pub depletion: Option<crate::BusinessDepletion>,
    /// Fees for ministerial services as a self-employed minister, religious-order member or Christian Science practitioner
    /// Weddings, baptisms, funerals, speeches and similar fees paid directly to you. Mark the whole ordinary business; do not mark farming or professional gambling.
    #[libertas_default(false)]
    pub ministerial: bool,
    /// Net profit from services as a notary public included in this business
    /// Exempt from self-employment tax. Enter only the net notary portion, not gross fees; zero if none.
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    #[libertas_default(0)]
    pub notary_profit: i64,
    /// Notary gross income already included in this business
    /// The notary share of gross income after its cost of goods, before other expenses. This is a source amount, not another receipt. An optional method with entered notary net profit needs this actual gross; without it the regular method applies. Enter the gross even when notary services produced no net profit.
    /// [NullText]
    /// No notary gross amount is supplied
    /// [SetText]
    /// Notary gross income included above is
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    #[libertas_default($null)]
    pub notary_gross: Option<i64>,

    /// Where business income is earned
    pub source: BusinessSource,
    /// Income-producing factors
    /// Distinguish the contribution of your personal services from material income-producing capital for young-filer tax rules. This is separate from QBI specified-service classification. Independent young filers can combine service-only, capital-only and mixed businesses. Each mixed activity uses its own reasonable compensation and attributable half-SE deduction; service-only profits and losses are combined separately. Capital/mixed-business dependents are supported when nonbusiness earnings, after the full half-SE deduction, already establish the maximum standard deduction; other dependent cases still need coordination.
    pub income_source: crate::BusinessIncomeSource,
    /// Activity and applicable expense limits
    pub activity: BusinessActivity,
    /// Inventory and cost of goods sold
    /// Farms use their own cash-basis or accrual inventory records; choose None here.
    pub inventory: crate::BusinessInventory,
    /// Start-up costs and their original election
    pub startup: crate::BusinessStartup,
    /// Accounting-method changes with a section 481(a) adjustment in 2026
    /// ----
    /// Change
    pub method_changes: Vec<crate::MethodChange>,
    /// Section 197 intangible assets
    /// Enter original business acquisition records, including continuing assets. These are separate from start-up costs and tangible equipment.
    pub intangibles: Vec<crate::BusinessIntangible>,
    /// Qualified timber costs and original section 194 elections
    /// Enter each direct property's expenditure-year cohort once, separate from
    /// ordinary expenses and entity statements. Missing original records and
    /// dispositions require further calculation before a complete estimate.
    pub timber: Vec<crate::BusinessTimberCost>,
    /// Other statutory amortization cost cohorts (Form4562-B)
    /// Research, pollution control, lease acquisition, preference write-offs and
    /// qualifying creative property. Keep original elections and actual history.
    pub other_amortization: Vec<crate::OtherAmortizableCost>,
    /// Owner health insurance, separate from business expenses
    pub health_insurance: crate::BusinessHealthInsurance,
    /// Owner retirement plan
    pub retirement: crate::BusinessRetirement,
    /// Vehicles using standard mileage
    /// Leave empty if none. Actual-expense vehicles require a separate worksheet.
    pub vehicles: Vec<crate::BusinessMileage>,
    /// Purchased business equipment
    /// Leave empty if none. Enter every qualifying asset once, using its recovery class and class-wide depreciation election. The App calculates the convention and retains business acquisition basis for QBI property limits.
    pub assets: Vec<crate::BusinessAsset>,
    /// Business expenses
    /// The App subtracts these expenses and calculated cost of goods sold from receipts. Do not list inventory or production costs here a second time.
    /// ----
    /// Business expense
    pub expenses: Vec<FederalBusinessExpense>,
    /// Qualified self-employed tips in this business
    /// These tips are already in Schedule C ordinary gross receipts or Schedule F other farm operating receipts. The App limits the deduction separately to this business's net income after its allocable deductions, then applies the shared annual cap and income phaseout. Leave empty when there are no qualified tips.
    pub tips: Option<FederalBusinessTips>,
    /// FLSA-qualified overtime separately reported on a 2026 Form 1099
    /// This premium is already in ordinary gross receipts. The App combines it with qualified W-2 overtime under the shared annual cap and income phaseout, without changing business profit or self-employment tax.
    pub overtime: Option<FederalBusinessOvertime>,
    /// Federal fuel tax paid on this business's qualified fuel
    /// The calculated credit is a refundable payment on Schedule 3 line 12. If full fuel cost was deducted, the App includes it in 2026 income only for an accrual-method activity. For cash-method activity, include it on the return for the year Form 4136 is filed; do not enter it in 2026 receipts merely because 2026 fuel was used.
    pub fuel_tax_credit: Option<FederalFuelTaxCredit>,
    /// Cash-method fuel-tax credit or refund included in 2026 income
    /// Record an original prior-year Form 4136 return filed in 2026, an amended prior-year credit received in 2026, or a fuel-tax refund received in 2026. Confirm either the full prior tax benefit or the narrowly documented partial 2025 benefit and avoid duplicating receipts. The 2026 return's own Form 4136 credit normally belongs in its later filing year.
    pub cash_fuel_tax_recovery: Option<FederalCashFuelRecovery>,
    /// Employer FICA credit for reported tips in an eligible business
    /// Use only for one directly owned, active U.S. food/beverage or qualifying beauty-service Schedule C employer with complete payroll records. The App computes Form 8846 and the related expense reduction from the same monthly records. Leave empty when no employer-tip credit is claimed.
    #[libertas_default($null)]
    pub employer_tip_fica_credit: Option<crate::EmployerTipFicaCredit>,
    /// Work opportunity credit for certified employees
    /// Use for wages this business paid in 2026 to employees certified for a targeted group who began work before 2026. The App computes Form 5884 and reduces the wages deduction by the credit. Leave empty when not claimed.
    #[libertas_default($null)]
    pub work_opportunity_credit: Option<crate::WorkOpportunityCredit>,
    /// Small employer retirement plan credits
    /// Use for a new employee retirement plan's start-up costs and automatic enrollment. The App computes Form 8881 Parts I and II and reduces the start-up costs deduction by that credit. Leave empty when not claimed.
    #[libertas_default($null)]
    pub retirement_plan_credit: Option<crate::RetirementPlanCredit>,
    /// Small employer health insurance premiums credit
    /// Use for premiums this business paid for its employees' SHOP Marketplace coverage. The App computes Form 8941 lines 1–16 and reduces the employee benefit programs deduction by the credit. Leave empty when not claimed.
    #[libertas_default($null)]
    pub small_employer_health_credit: Option<crate::SmallEmployerHealthCredit>,
    /// Employer credit for paid family and medical leave
    /// Use for wages this business paid to qualifying employees on family and medical leave, or premiums for a paid leave insurance policy. The App computes Form 8994 lines 1a–3 and reduces the wages and employee benefit programs deductions by the credit. Leave empty when not claimed.
    #[libertas_default($null)]
    pub paid_leave_credit: Option<crate::PaidLeaveCredit>,
    /// Actively and materially participated in this business
    /// Apply the seven tests of Reg. 1.469-5T(a) to your time records, for example more than 500 hours. No leaves this business out of the estimate with a notice; a passive business is not supported.
    pub material_participation: bool,
    /// Specified service trade or business for the QBI deduction
    /// Includes health, law, accounting, actuarial science, performing arts, consulting, athletics, financial/brokerage services, investing/trading and dealing in securities. Architecture and engineering are excluded. Check the business’s actual services and retained Section 199A records.
    pub specified_service: bool,
    /// At-risk investment and loss limitations (Form 6198)
    pub at_risk: crate::RentalAtRisk,
    /// Employee payroll
    pub payroll: crate::BusinessPayroll,
    /// Unlisted inventory treatment, depreciation/amortization beyond the entered assets, unlisted home-office treatment, unlisted farming rules, partnership/S-corporation, foreign treatment beyond the selected source, prior losses or another special tax election applies
    /// These are your own elections, books and prior returns. Yes leaves this business out of the estimate with a notice; that treatment is not supported.
    pub special_treatment: bool,
    /// Aggregation group for the QBI deduction
    /// Leave empty unless you elect to treat this activity as part of one combined trade or business. Give the same group name to every business or rental in the group. Each member must be at least 50% owned by the same person or group for most of the year, including the last day of the year; use the same tax year; not be a specified service trade or business; and share at least two of these: the same or customary related products or services, shared facilities or centralized business elements, and coordinated or interdependent operation. An elected group must be kept in later years. The group affects only the wage and property limit above the income threshold.
    #[libertas_size(min = 1)]
    #[libertas_default($null)]
    pub qbi_aggregation_group: Option<String>,
    /// Federal income tax withheld on Forms 1099-NEC, 1099-MISC or 1099-K for this business
    #[libertas_default(0)]
    pub withholding: i64,
    /// Commercial fishing business
    /// Catching, taking, harvesting or farming fish, shellfish, crustaceans, sponges, seaweed or other aquatic life. Used for the farming and fishing estimated-tax test.
    #[libertas_default(false)]
    pub commercial_fishing: bool,
    /// Sale of the business as a whole (Form 8594)
    /// Leave empty unless you sold the whole business in 2026.
    #[libertas_default($null)]
    pub sale: Option<crate::BusinessSale>,
}

impl FederalBusiness {
    pub(crate) fn cash_accounting(&self) -> bool {
        match &self.activity {
            BusinessActivity::Ordinary { accounting, .. } => {
                *accounting == BusinessAccounting::Cash
            }
            BusinessActivity::Farming { data } => {
                matches!(data.accounting, crate::FarmAccounting::Cash { .. })
            }
            BusinessActivity::Gambling { accounting, .. } => {
                *accounting == BusinessAccounting::Cash
            }
        }
    }

    pub(crate) fn accrual_accounting(&self) -> bool {
        match &self.activity {
            BusinessActivity::Ordinary { accounting, .. } => {
                *accounting == BusinessAccounting::Accrual
            }
            BusinessActivity::Farming { data } => {
                matches!(data.accounting, crate::FarmAccounting::Accrual { .. })
            }
            BusinessActivity::Gambling { accounting, .. } => {
                *accounting == BusinessAccounting::Accrual
            }
        }
    }

    pub(crate) fn receipts(&self) -> i64 {
        self.activity.receipts()
            + self.other_income.iter().map(|v| v.amount).sum::<i64>()
            + crate::method_change::increase(&self.method_changes)
            // Schedule C line 6: recapture of excess depreciation on listed property
            // whose business use fell to 50% or less (Form 4797 Part IV).
            + self
                .assets
                .iter()
                .filter_map(|asset| asset.recapture().or_else(|| asset.section179_recapture()))
                .map(|recapture| recapture.excess())
                .sum::<i64>()
            // Schedule C line 6: a covenant is Schedule 1 line 8z, the
            // inventory sold with the business is a sale on line 1.
            + self
                .sale
                .as_ref()
                .filter(|sale| sale.supported())
                .map_or(0, |sale| sale.inventory)
            + self
                .cash_fuel_tax_recovery
                .as_ref()
                .map_or(0, |v| v.taxable_amount())
            + self.fuel_tax_credit.as_ref().map_or(0, |claim| {
                if self.accrual_accounting()
                    && claim.expense_treatment == FederalFuelExpenseTreatment::FullCostDeducted
                {
                    claim.expense_recovery_cents()
                } else {
                    0
                }
            })
            + self.fuel_tax_credit.as_ref().map_or(0, |claim| {
                if self.accrual_accounting() {
                    claim
                        .fuels
                        .card_issuer
                        .as_ref()
                        .map_or(0, crate::FederalCardIssuerClaim::retained_income_cents)
                } else {
                    0
                }
            })
    }
    pub(crate) fn se_exclusion(&self) -> i64 {
        match &self.activity {
            BusinessActivity::Farming { data } => {
                data.crp.iter().map(crate::CrpPayment::se_exclusion).sum()
            }
            _ => 0,
        }
    }
    pub(crate) fn earned_receipts(&self) -> i64 {
        self.receipts() - self.se_exclusion()
    }
    pub(crate) fn operating_cost_with_adjustment(&self, mid_quarter: bool, additional: i64) -> i64 {
        self.operating_cost_with_supplies(
            self.operating_cost_before_supplies(mid_quarter) + additional,
        )
    }
    pub(crate) fn operating_cost_with_supplies(&self, other: i64) -> i64 {
        other
            + match &self.activity {
                BusinessActivity::Farming { data } => {
                    data.supplies.as_ref().map_or(0, |s| s.amounts(other, self)[2])
                }
                _ => 0,
            }
    }
    // Schedule C line 23 beyond the taxes-and-licenses category: the employer
    // Social Security and Medicare tax on reported tips that Form 8846 does not
    // take (2026 i1040sc line 23: "Reduce your deduction by the amount shown on
    // Form 8846, line 4") and the business share of a standard-mileage
    // vehicle's personal property tax (line 9, "Standard mileage rate").
    pub(crate) fn line23_additions(&self) -> i64 {
        self.employer_tip_fica_credit
            .as_ref()
            .map_or(0, |claim| claim.remaining_fica_deduction_cents())
            + crate::BusinessMileage::property_tax(&self.vehicles)
    }
    // Schedule C Part V (line 48, carried to line 27b) beyond the Other
    // categories: the start-up cost deduction and amortization and the
    // section 197 amortization (2026 i1040sc Part V).
    pub(crate) fn checked_amortization_cents(&self) -> Option<i64> {
        crate::kernel::ratio::checked_sum(
            core::iter::once(self.startup.deduction())
                .chain(self.intangibles.iter().map(crate::BusinessIntangible::deduction))
                .chain(core::iter::once(crate::timber::deduction(&self.timber)?))
                .chain(core::iter::once(crate::cohorts::deduction(
                    &self.other_amortization,
                    &self.assets,
                )?)),
        )
    }
    pub(crate) fn amortization_cents(&self) -> i64 {
        // Native accepted-source accessor. Save validation and the estimator's
        // existing stored_issue boundary run before these operating-cost callers.
        if self.timber.is_empty() && self.other_amortization.is_empty() {
            self.startup.deduction()
                + self.intangibles.iter().map(crate::BusinessIntangible::deduction).sum::<i64>()
        } else {
            self.checked_amortization_cents().expect("validated amortization total")
        }
    }
    // The Form 8881 start-up credit (line 5) that reduces the deduction for
    // the plan's start-up costs (section 45E(e)(2)).
    pub(crate) fn plan_startup_credit_cents(&self) -> i64 {
        self.retirement_plan_credit.as_ref().map_or(0, |claim| claim.startup_credit() * 100)
    }
    pub(crate) fn checked_operating_cost_before_supplies(&self, mid_quarter: bool) -> Option<i64> {
        let original_amortization = self.startup.deduction()
            + self.intangibles.iter().map(crate::BusinessIntangible::deduction).sum::<i64>();
        self.operating_cost_with_amortization(mid_quarter, original_amortization)
            .checked_add(crate::timber::deduction(&self.timber)?)?
            .checked_add(crate::cohorts::deduction(&self.other_amortization, &self.assets)?)
    }
    pub(crate) fn operating_cost_before_supplies(&self, mid_quarter: bool) -> i64 {
        if self.timber.is_empty() && self.other_amortization.is_empty() {
            self.operating_cost_with_amortization(mid_quarter, self.amortization_cents())
        } else {
            self.checked_operating_cost_before_supplies(mid_quarter)
                .expect("validated operating costs including timber")
        }
    }
    pub(crate) fn operating_cost_with_asset_deductions(&self, depreciation: i64) -> Option<i64> {
        Some(self.operating_cost_with_recovery(self.checked_amortization_cents()?, depreciation))
    }
    fn operating_cost_with_amortization(&self, mid_quarter: bool, amortization: i64) -> i64 {
        self.operating_cost_with_recovery(
            amortization,
            self.assets.iter().map(|asset| asset.deduction(mid_quarter)).sum::<i64>(),
        )
    }
    fn operating_cost_with_recovery(&self, amortization: i64, depreciation: i64) -> i64 {
        (match &self.activity {
            BusinessActivity::Farming { data } => {
                data.conservation.as_ref().map_or(0, |c| {
                    c.deduction(data.gross() + crate::method_change::increase(&self.method_changes))
                }) + data.ccc.as_ref().map_or(0, crate::FarmCcc::deficiency)
                    + data.specials.fertilizer_deduction()
                    + data.specials.production_deduction(matches!(data.accounting,crate::FarmAccounting::Cash {..}),false)
            }
            _ => 0,
        }) + FederalBusinessExpense::total(&self.expenses)
            // Ordinary expenses omit employer FICA on reported tips. Section
            // 45B allows only the tax not claimed on Form 8846.
            + self.employer_tip_fica_credit.as_ref().map_or(0, |claim| {
                claim.remaining_fica_deduction_cents()
            })
            - self.work_opportunity_credit.as_ref().map_or(0, |claim| claim.credit() * 100)
            - self.plan_startup_credit_cents()
            - self
                .small_employer_health_credit
                .as_ref()
                .map_or(0, |claim| claim.credit(&self.payroll) * 100)
            - self.paid_leave_credit.as_ref().map_or(0, |claim| claim.credit() * 100)
            + self.inventory.cost()
            + amortization
            + self.depletion.as_ref().map_or(0, |v| match v.depletion {
                crate::RoyaltyDepletion::Cost { adjusted_basis, recoverable_units, units_sold }
                    if recoverable_units > 0 =>
                {
                    crate::kernel::ratio::fraction(adjusted_basis, units_sold, recoverable_units)
                }
                _ => 0,
            })
            + self.de_minimis.as_ref().map_or(0, |v| v.purchases)
            + self.leased_vehicles.iter().map(|v| v.amounts().total()).sum::<i64>()
            + crate::method_change::decrease(&self.method_changes)
            + crate::BusinessMileage::total(&self.vehicles)
            + self.assets.iter().map(crate::BusinessAsset::vehicle_operating).sum::<i64>()
            + self.assets.iter().map(crate::BusinessAsset::vehicle_loan_interest).sum::<i64>()
            + depreciation
    }
    pub(crate) fn expense_total(&self, mid_quarter: bool) -> i64 {
        self.expense_with_adjustment(mid_quarter, 0)
    }
    pub(crate) fn expense_with_adjustment(&self, mid_quarter: bool, additional: i64) -> i64 {
        self.expense_from_operating(self.operating_cost_with_adjustment(mid_quarter, additional))
    }
    pub(crate) fn expense_from_operating(&self, operating: i64) -> i64 {
        self.expense_with_office(operating, 0)
    }
    // Operating costs plus the Schedule C line 30 amount already figured.
    pub(crate) fn expense_with_office(&self, operating: i64, office: i64) -> i64 {
        let expenses = operating + office;
        match self.activity {
            BusinessActivity::Ordinary { .. } | BusinessActivity::Farming { .. } => expenses,
            BusinessActivity::Gambling { losses, .. } => phase::cap(
                self.receipts(),
                [crate::kernel::ratio::fraction(losses + expenses, 90, 100)],
            ),
        }
    }
}

/// Prior personal-property rental losses
/// Suspended expenses from retained Form 8582 worksheets; leave both at zero when there are none. Enter them only for the same owner and continuing activity, with complete expense records: only fully at-risk nonbusiness operating expenses or depreciation suspended by the passive rules and reportable on Schedule 1. Depreciation has already reduced the asset's basis; releasing this deduction does not reduce basis again. No capital losses, interest, credits, QBI, ownership changes, dispositions, grouping changes or change to a nonrental activity. Do not also enter these deductions as current paid expenses or current depreciation.
#[derive(
    Clone, Copy, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport,
)]
pub struct PersonalRentalHistory {
    /// Regular-tax suspended deductions for this activity
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    #[libertas_default(0)]
    pub regular: i64,
    /// Separately tracked AMT suspended deductions
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    #[libertas_default(0)]
    pub amt: i64,
}
impl PersonalRentalHistory {
    /// No suspended deductions.
    #[cfg(test)]
    pub(crate) const NONE: Self = Self { regular: 0, amt: 0 };
    pub(crate) fn balance(self, alternative: bool) -> i64 {
        if alternative { self.amt } else { self.regular }
    }
}

/// Nonbusiness property income source
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
pub enum NonbusinessPropertyKind {
    /// Personal-property rental for profit, outside a rental business
    /// Equipment and other movable property; not real estate. Business rentals belong in Business.
    PersonalRental {
        /// Total unadjusted basis of property in this rental activity
        /// Original tax basis before depreciation deductions, including all property rented together in this activity. Do not use current remaining basis or fair market value. Use zero when the original tax-basis records establish zero; a fully depreciated asset can still have a positive unadjusted basis.
        #[libertas_money("USD", 2)]
        #[libertas_number(min = 0)]
        basis: i64,
        /// Unadjusted basis of the part subject to depreciation
        /// Use the original basis of depreciable property even if it is now fully depreciated. The App compares this with total basis to determine whether net income is recharacterized for the investment-interest limit.
        #[libertas_money("USD", 2)]
        #[libertas_number(min = 0)]
        depreciable_basis: i64,
        /// Purchased rental equipment
        /// Enter every asset requiring current depreciation, once in this activity. Use 100% income-producing use and Section 179 ineligible: a nonbusiness rental cannot claim section 179. Already fully recovered property may be omitted here but remains in the unadjusted basis above. Include this property in the return-wide bonus/method elections and convention test. No listed property, vehicles, ADS or personal conversions.
        assets: Vec<crate::BusinessAsset>,
        /// Prior suspended deductions
        history: PersonalRentalHistory,
    },
}

impl NonbusinessPropertyKind {
    pub(crate) fn rental_depreciation(&self, mid_quarter: bool, amt: bool) -> i64 {
        match self {
            Self::PersonalRental { assets, .. } => {
                assets.iter().map(|a| a.deduction_for(mid_quarter, amt)).sum()
            }
        }
    }

    pub(crate) fn prior_rental_loss(&self, alternative: bool) -> i64 {
        match self {
            Self::PersonalRental { history, .. } => history.balance(alternative),
        }
    }
    pub(crate) fn investment_rental(&self) -> bool {
        matches!(self, Self::PersonalRental { basis, depreciable_basis, .. }
            if i128::from(*depreciable_basis) * 10 < i128::from(*basis) * 3)
    }
}

/// Beneficiary Schedule K-1 (Form 1041) for 2026
/// Enter the boxes as reported by the fiduciary. Box 5 supports ordinary nonbusiness royalties, including limited directly apportioned box 9 code A sound-recording depreciation, code B cost depletion or code C amortization from the same activity. Boxes 6–8 business and rental income enter Schedule E line 33 with their box 9 deductions, the passive-activity rules and the box 14 code I trade or business QBI statement. Limited box 10 IRD-interest estate tax and final-year box 11 codes A–F require their source confirmations. Standalone box 12 code A or a confirmed complete code B/C/D component reconciliation, including code E/F portions within D, and limited box 14 codes F/H/I use their respective estimated-tax, AMT, NIIT and section 199A calculations. Other K-1 income, deduction, credit, AMT or foreign-source items, including unentered attachments, need their own calculations.
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
pub struct FederalEstateTrustPortfolioK1 {
    /// Final-year source character and beneficiary entitlement
    pub final_character: Option<crate::EstateFinalCharacter>,
    /// Signed box 12 reconciliation and activity allocations
    pub amt_reconciliation: Option<crate::EstateAmtReconciliation>,
    /// Box 14 code E source net investment income for Form 4952
    pub investment_income: Option<crate::EstateInvestmentIncome>,
    /// Box 13 credit statements by their Form 1041 code identity
    // Tax structure: one statement per supported Form 1041 box 13 credit code.
    #[libertas_size(max = 19)]
    pub reported_credits: Vec<crate::EstateReportedCredit>,
    /// Box 14 code B foreign tax statement
    pub foreign_statement: Option<crate::EstateForeignStatement>,
    /// Fiduciary investment-credit property source statements
    pub investment_property: Vec<crate::EstateInvestmentProperty>,

    /// Estate's or trust's EIN from item A; all nine digits without punctuation
    // Legal identifier: an EIN is exactly nine digits without punctuation.
    #[libertas_size(min = 9, max = 9)]
    #[libertas_pattern("[0-9]{9}")]
    pub ein: String,
    /// Box 1 taxable interest — Form 1040 line 2b
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub interest: i64,
    /// Box 2a ordinary dividends — Form 1040 line 3b
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub ordinary_dividends: i64,
    /// Box 2b qualified dividends, included in box 2a — Form 1040 line 3a
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub qualified_dividends: i64,
    /// Box 14 code I section 199A dividends included in box 2a ordinary dividends
    /// Enter only the beneficiary's apportioned qualified REIT/RIC dividends from the fiduciary's statement, separate from box 2b qualified dividends.
    pub section199a_dividends: crate::ReitDividends,
    /// The box 14 code I statement contains only section 199A dividends for this portfolio K-1
    /// Confirm when section 199A dividends are entered. Business QBI, PTP amounts, W-2 wages, property basis and cooperative items need their own worksheets.
    pub code_i_dividends_only: bool,
    /// Box 3 net short-term capital gain — Schedule D line 5
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub short_gain: i64,
    /// Box 4a net long-term capital gain — Schedule D line 12
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub long_gain: i64,
    /// Box 4b 28% rate gain, included in box 4a
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub rate_28_gain: i64,
    /// Box 4c unrecaptured section 1250 gain, included in box 4a
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub unrecaptured_gain: i64,
    /// Box 5 other portfolio income — entirely ordinary nonbusiness royalties reported on Schedule E line 33(f)
    /// Do not enter annuities, income in respect of a decedent or business royalties here. Enter supported directly apportioned depreciation, cost depletion or amortization separately below; other deductions need other calculations.
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub royalty_income: i64,
    /// The entire box 5 amount is ordinary domestic nonbusiness royalties with no unentered NIIT adjustment
    /// Confirm when box 5 royalties are entered. A limited box 9 code A, B or C deduction below may come from the same activity; enter a separately reported box 14 code H adjustment below only when no box 9 deduction is entered. Other box 5 characters need their own calculations.
    pub box_5_royalty_only: bool,
    /// Box 9 code A depreciation directly apportioned to the box 5 sound-recording royalty activity
    /// Enter only the beneficiary's deduction from the fiduciary's per-activity statement, separate from box 5 income and no greater than that income in this supported nonloss path.
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub box_9_royalty_depreciation: i64,
    /// The entire box 9 code A deduction is confirmed section 167 straight-line depreciation of one fiduciary-held master sound recording
    /// Confirm the recording was licensed for domestic nonbusiness royalties and held by the fiduciary throughout 2026. Retain the fiduciary's per-asset basis, placed-in-service date, useful-life and beneficiary-allocation statement. The straight-line schedule began before 2026; no section 181 expensing, section 168(k) bonus, section 197 amortization, income-forecast look-back, other box 9 item, box 12 code G or box 14 code H applies. Regular, AMT and NIIT deductions agree, with no separate beneficiary limit or property succession.
    pub box_9_royalty_sound_recording_only: bool,
    /// Box 9 code B cost depletion directly apportioned to the box 5 mineral royalty activity
    /// Enter only the beneficiary's deduction from the fiduciary's per-activity statement, separate from box 5 income and no greater than that income in this supported nonloss path.
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub box_9_royalty_depletion: i64,
    /// The entire box 9 code B deduction is confirmed cost depletion on one fiduciary-held domestic nonbusiness mineral royalty property
    /// Confirm the fiduciary held the property throughout 2026 and supplied a per-property account showing its adjusted depletion basis, recoverable and sold units, cost-depletion calculation and complete beneficiary allocation. Retain that statement as the beneficiary's depletion record. Cost depletion must be the allowable method, not percentage depletion. Regular and AMT property bases and deductions agree, with no box 12 code H, box 14 code H overlap, separate beneficiary-level limit, or other box 9 deduction.
    pub box_9_royalty_cost_depletion_only: bool,
    /// Box 9 code C amortization directly apportioned to the box 5 royalty activity
    /// Enter the beneficiary's amount from the fiduciary's activity statement, not the trust's total amortization. It must be separate from box 5 income and no greater than that income in this supported nonloss path.
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub box_9_royalty_amortization: i64,
    /// The box 9 code C deduction is one confirmed section 197 royalty-activity amortization
    /// Confirm a single domestic nonbusiness section 212 royalty activity, an eligible section 197 intangible with a pre-2026 straight-line schedule, the fiduciary's complete beneficiary allocation, and no other box 9 item. The deduction must be fully allowable for regular tax, AMT and NIIT in the same amount, with no box 12 code I, box 14 code H overlap, or separate beneficiary-level limit.
    pub box_9_royalty_amortization_only: bool,
    /// Fiduciary activity statements for boxes 6–9
    pub activities: crate::EstateActivities,
    /// Fiduciary-apportioned section 199A source statements
    pub qbi: crate::EstateQbiStatements,
    /// Box 14 code F gross farming and fishing income included in box 6 — Schedule E line 42
    /// Used only for the farmer and fisherman estimated-tax test; it does not add income again.
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub gross_farming_fishing_income: i64,
    /// Box 10 section 691(c) estate-tax deduction on income in respect of a decedent — Schedule A line 17e
    /// Enter only the fiduciary-allocated amount attributable entirely to taxable IRD interest included in this K-1's box 1, with no box 14 code H adjustment that may already include it. Mixed or capital-gain IRD requires separate worksheets.
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub box_10_interest_ird_estate_tax: i64,
    /// The entire box 10 deduction is attributable to taxable IRD interest included in box 1
    /// Confirm from the fiduciary's allocation when box 10 is entered. The deduction is itemized and its properly allocable share reduces net investment income only when itemized.
    pub box_10_interest_ird_only: bool,
    /// Final-year box 11 code A section 67(e) excess deduction — Schedule 1 line 24k
    /// Enter only the amount allocated by the fiduciary to this beneficiary, not all estate or trust expenses. This deduction cannot be carried to another beneficiary tax year.
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub final_67e_deduction: i64,
    /// The box 11 code A deduction has no amount properly allocable to net investment income
    /// Confirm from the fiduciary's allocation when the deduction is entered. An investment-related part needs its separate Form 8960 treatment.
    pub final_67e_no_niit_allocation: bool,
    /// Final-year box 11 code B non-miscellaneous itemized deduction consisting of annual value-based personal property tax
    /// Enter only the amount allocated to this beneficiary by the fiduciary after the estate or trust's final-year income allocation. The beneficiary's own SALT limit applies; unused excess cannot carry to another beneficiary year.
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub final_personal_property_tax: i64,
    /// Final-year box 11 code B noninvestment, nonbusiness real-estate tax — Schedule A line 5b
    /// Enter only the fiduciary's beneficiary allocation of uniformly assessed real-property tax for general public purposes, with no business, rental or investment-use portion. It joins the beneficiary's own SALT limit; unused excess cannot carry to another year.
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub final_real_estate_tax: i64,
    /// Final-year box 11 code B state or local income tax — Schedule A line 5a if income taxes are elected
    /// Enter only the beneficiary amount remaining after the fiduciary's own section 164 limit. The beneficiary's SALT limit applies again. The tax has no Form 8960 investment-income allocation; otherwise use a separate worksheet. When general sales tax is elected, this income tax is not deducted.
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub final_state_income_tax: i64,
    /// Final-year box 11 code B state or local general sales tax — Schedule A line 5a if sales taxes are elected
    /// Enter only the beneficiary amount remaining after the fiduciary's own section 164 limit. The beneficiary's SALT limit applies again. The amount is not deductible under the beneficiary's state-income-tax election.
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub final_state_sales_tax: i64,
    /// The entire box 11 code B amount is deductible state/local income or general sales tax, noninvestment real-estate tax or nonbusiness personal-property tax
    /// Confirm the fiduciary's separate statement and beneficiary succession. Other code B tax or itemized-deduction classes need their own worksheets.
    pub final_taxes_only: bool,
    /// Final-year box 11 code C short-term capital loss carryover — Schedule D line 5
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub final_short_carry: i64,
    /// Final-year box 11 code D long-term capital loss carryover — Schedule D line 12
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub final_long_carry: i64,
    /// The estate or trust terminated in 2026 and this beneficiary succeeds to its property
    /// Confirm when a box 11 code A, B, C, D, E or F amount is entered. The K-1 must show the final Form 1041 and allocated amount.
    pub final_year_successor: bool,
    /// Final-year capital loss carryovers have the same regular, AMT, investment-property and net-investment-income tax character
    /// Confirm from the fiduciary's records when either carryover is entered; a difference needs separate worksheets.
    pub final_carry_same_tax_character: bool,
    /// Final-year box 11 codes E/F regular and alternative-tax NOL carryovers by original loss year
    /// Enter the beneficiary's remaining balances after the estate's or trust's required carrybacks and intervening returns. Keep each original year and regular/AMT amount separate; the box totals are their sums.
    pub final_nol: Option<FinalEstateTrustNol>,
    /// Box 12 code A adjustment for minimum tax purposes — Form 6251 line 2j
    /// Enter the signed beneficiary adjustment shown on the K-1. It may stand alone or equal the sum of its confirmed code B qualified-dividend, C short-term and D long-term components. Codes E and F may be disjoint same-sign portions of D. Opposite-sign component netting, related income-based adjustments, loss-source reallocation and foreign-tax-credit allocation need separate worksheets.
    #[libertas_money("USD", 2)]
    pub amt_box12a: i64,
    /// Box 12 code A stands alone with no other AMT items or related adjustments
    /// Confirm when code A is entered. If boxes 12 B–J, a companion statement or related income-based adjustment applies, the AMT calculation needs its separate worksheet.
    pub amt_box12a_standalone: bool,
    /// Box 12 code B portion of code A attributable to qualified dividends
    /// Enter the signed amount shown by the fiduciary. It changes AMT preferential rates, not regular Form 1040 dividends.
    #[libertas_money("USD", 2)]
    pub amt_box12b: i64,
    /// Every box 12 code A component is identified and reconciled to codes B, C and D
    /// Confirm the signed code A amount exactly equals the sum of all reported B qualified-dividend, C short-term and D long-term adjustments, with no other code A component or related AMT statement omitted. Every nonzero component must have A's sign. Codes E/F are disjoint portions of D and need their own confirmations below. Separate investment-interest and foreign-exclusion worksheets remain outside this path.
    pub amt_box12_components_confirmed: bool,
    /// Box 12 code C portion of code A attributable to net short-term capital gain
    /// Enter the signed fiduciary adjustment. It changes AMT Schedule D line 5 and the AMT rate worksheet, not regular Schedule D or AGI; the same amount remains included once in code A.
    #[libertas_money("USD", 2)]
    pub amt_box12c: i64,
    /// Box 12 code D portion of code A attributable to net long-term capital gain
    /// Enter the signed fiduciary adjustment. It changes AMT Schedule D line 12 and the AMT rate worksheet, not regular Schedule D or AGI; the same amount remains included once in code A.
    #[libertas_money("USD", 2)]
    pub amt_box12d: i64,
    /// Box 12 code E portion of code A attributable to unrecaptured section 1250 gain
    /// Enter the signed fiduciary adjustment for line 11 of the AMT Unrecaptured Section 1250 Gain Worksheet. Code E may be all or a same-sign portion of D: section 1250 gain is part of long-term capital gain, not another addition to AMTI.
    #[libertas_money("USD", 2)]
    pub amt_box12e: i64,
    /// Box 12 code E is included in code D long-term gain adjustment
    /// Confirm the fiduciary identified code E within signed code D. If F is also reported, E and F are disjoint; the remainder of D after both is ordinary long-term gain. E must have D's sign, and the E/F magnitudes together cannot exceed D. Form 4952 and Form 2555 require separate coordination.
    pub amt_box12e_included_in_d: bool,
    /// Box 12 code F portion of code A attributable to 28%-rate gain
    /// Enter the signed fiduciary amount. Code F may be all or a same-sign portion of D. D refigures AMT Schedule D line 12; F refigures line 4 of the AMT 28% Rate Gain Worksheet without another AMTI addition.
    #[libertas_money("USD", 2)]
    pub amt_box12f: i64,
    /// Box 12 code F is included in code D long-term gain adjustment
    /// Confirm the fiduciary identified code F within signed code D. If E is also reported, E and F are disjoint; the remainder of D after both is ordinary long-term gain. F must have D's sign, and the E/F magnitudes together cannot exceed D. Form 4952 and Form 2555 require separate coordination.
    pub amt_box12f_included_in_d: bool,
    /// Box 13 code B backup withholding — Form 1040 federal withholding payments
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub backup_withholding: i64,
    /// Box 13 code A estimated-tax payment allocated to this beneficiary — Form 1040 line 26
    /// Do not also enter this amount among the filer's own estimated payments.
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub allocated_estimated_tax: i64,
    /// The fiduciary timely filed Form 1041-T allocating the box 13 code A payment to this beneficiary
    /// Item D of the K-1 shows it. The payment is treated as paid January 15, 2027 for Form 2210; without a timely Form 1041-T it stays the estate's or trust's payment and is left out.
    pub form_1041t_timely: bool,
    /// Box 14 code A tax-exempt interest — Form 1040 line 2a
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub tax_exempt_interest: i64,
    /// Specified private-activity-bond interest included in box 14 code A tax-exempt interest
    /// Enter only the fiduciary-identified beneficiary share; this is an AMT preference, not additional regular income.
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub private_activity_interest: i64,
    /// Box 14 code H net investment income adjustment, if shown
    /// Enter the fiduciary's separate Form 8960 line 7 adjustment and its modified-AGI effect. Do not repeat portfolio income already entered in boxes 1–5.
    pub niit_adjustment: Option<EstateTrustNiitAdjustment>,
    /// Other boxes on this K-1 with an amount
    /// ----
    /// Box with an amount
    // Tax structure: each supported other K-1 box identity occurs at most once.
    #[libertas_size(max = 13)]
    pub unentered: Vec<EstateTrustK1Item>,
    /// This K-1's income sources and beneficiary treatment are classified
    /// No means unclassified income, foreign-beneficiary or inconsistent-return facts need their owning worksheet. Known income remains included, but these facts prevent a complete federal estimate.
    pub complete_portfolio_only: bool,
    /// Actual current Schedule K-1 entity period and accounting convention
    /// Ordinary current-year sources may leave this absent. Retain actual dates and election statements for a 52/53-week source; do not replace dates with a deemed calendar year.
    #[libertas_default($null)]
    pub entity_period: Option<FinalEstateTrustTaxPeriod>,
    /// Box 12 code J exclusion items for the following year's minimum tax credit
    /// Signed fiduciary component of code A, retained without a second current-year AMT adjustment. Absent and reported zero remain distinct.
    #[libertas_money("USD", 2)]
    #[libertas_default($null)]
    pub minimum_tax_exclusion: Option<i64>,
}

impl FederalEstateTrustPortfolioK1 {
    pub(crate) fn valid(&self) -> bool {
        crate::estate_trust::ein_valid(&self.ein)
            && [
                self.interest,
                self.ordinary_dividends,
                self.qualified_dividends,
                self.short_gain,
                self.long_gain,
                self.rate_28_gain,
                self.unrecaptured_gain,
                self.royalty_income,
                self.box_9_royalty_depreciation,
                self.box_9_royalty_depletion,
                self.box_9_royalty_amortization,
                self.box_10_interest_ird_estate_tax,
                self.final_67e_deduction,
                self.final_personal_property_tax,
                self.final_real_estate_tax,
                self.final_state_income_tax,
                self.final_state_sales_tax,
                self.final_short_carry,
                self.final_long_carry,
                self.backup_withholding,
                self.allocated_estimated_tax,
                self.tax_exempt_interest,
                self.private_activity_interest,
                self.gross_farming_fishing_income,
            ]
            .into_iter()
            .all(|amount| (0..=100_000_000_000).contains(&amount))
            && crate::estate_trust::source_rule(self).is_none()
            && self.activities.rule().is_none()
            && self.qbi.rule(&self.activities).is_none()
            && self.qualified_dividends + self.section199a_dividends.amount()
                <= self.ordinary_dividends
            && (0..=100_000_000_000).contains(&self.section199a_dividends.amount())
            && self.rate_28_gain + self.unrecaptured_gain <= self.long_gain
            && self.private_activity_interest <= self.tax_exempt_interest
            && (-100_000_000_000..=100_000_000_000).contains(&self.amt_box12a)
            && (-100_000_000_000..=100_000_000_000).contains(&self.amt_box12b)
            && (-100_000_000_000..=100_000_000_000).contains(&self.amt_box12c)
            && (-100_000_000_000..=100_000_000_000).contains(&self.amt_box12d)
            && (-100_000_000_000..=100_000_000_000).contains(&self.amt_box12e)
            && (-100_000_000_000..=100_000_000_000).contains(&self.amt_box12f)
            && self.qualified_dividends + self.amt_box12b >= 0
            && self.niit_adjustment.as_ref().is_none_or(EstateTrustNiitAdjustment::valid)
            && self.final_nol.as_ref().is_none_or(FinalEstateTrustNol::valid)
            && self
                .unentered
                .iter()
                .enumerate()
                .all(|(index, item)| !self.unentered[..index].contains(item))
    }
}

/// Other K-1 box with an amount
#[derive(
    Clone, Copy, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport,
)]
#[libertas_inline_choices]
pub enum EstateTrustK1Item {
    /// Box 12 codes G, H or I — depreciation, depletion or amortization adjustments
    AmtItems,
    /// Box 13 credit not entered above (other than code R recapture)
    Credits,
    /// Box 13 code R — credit recapture statement requiring additional tax
    CreditRecapture,
    /// Unclassified box 14 information — the actual income, tax or return treatment is not determined
    /// Use the separately named category below for an identified unentered benefit. Unclassified income or added tax needs the fiduciary's statement before a complete estimate.
    OtherInformation,
    /// Box 14 code B — foreign taxes not entered in the foreign-tax statement
    ForeignTaxes,
    /// Box 14 code C — qualified rehabilitation expenditures not entered in investment property
    Rehabilitation,
    /// Box 14 code D — energy property basis not entered in investment property
    EnergyProperty,
    /// Box 14 code E — net investment income not entered in its Form 4952 source
    InvestmentIncome,
    /// Box 14 code G — foreign trading gross receipts; extraterritorial-income exclusion not calculated
    ForeignTradingGrossReceipts,
    /// Box 14 code J — qualifying advanced coal or gasification project property
    AdvancedCoalGasification,
    /// Box 14 code K — qualifying advanced energy project property
    AdvancedEnergy,
    /// Box 14 code L — advanced manufacturing investment property
    AdvancedManufacturing,
    /// Box 14 code M — clean electricity investment credit property not entered in investment property
    CleanElectricity,
}

impl EstateTrustK1Item {
    pub(crate) fn benefit_notice_key(self) -> Option<&'static str> {
        Some(match self {
            Self::ForeignTaxes => "WARN_ESTATE_BOX14_B_LEFT_OUT",
            Self::Rehabilitation => "WARN_ESTATE_BOX14_C_LEFT_OUT",
            Self::EnergyProperty => "WARN_ESTATE_BOX14_D_LEFT_OUT",
            Self::InvestmentIncome => "WARN_ESTATE_BOX14_E_LEFT_OUT",
            Self::ForeignTradingGrossReceipts => "WARN_ESTATE_BOX14_G_LEFT_OUT",
            Self::AdvancedCoalGasification => "WARN_ESTATE_BOX14_J_LEFT_OUT",
            Self::AdvancedEnergy => "WARN_ESTATE_BOX14_K_LEFT_OUT",
            Self::AdvancedManufacturing => "WARN_ESTATE_BOX14_L_LEFT_OUT",
            Self::CleanElectricity => "WARN_ESTATE_BOX14_M_LEFT_OUT",
            _ => return None,
        })
    }
    #[cfg(test)]
    pub(crate) fn refusal(self) -> Option<&'static str> {
        self.refusal_info().map(|info| info.1)
    }
    pub(crate) fn refusal_key(self) -> Option<&'static str> {
        self.refusal_info().map(|info| info.0)
    }
    fn refusal_info(self) -> Option<(&'static str, &'static str)> {
        Some(match self {
            Self::AmtItems => (
                "ISSUE_ESTATE_K1_AMT_ITEMS",
                crate::fixture_english!(
                    "An unentered Schedule K-1 (1041) box 12 code G, H or I needs its signed amount and applicable Form 6251 line or activity treatment. The mandatory AMT adjustment cannot be omitted."
                ),
            ),
            Self::CreditRecapture => (
                "ISSUE_ESTATE_K1_CREDIT_RECAPTURE",
                crate::fixture_english!(
                    "Schedule K-1 (1041) box 13 code R requires the applicable credit-recapture tax calculation; this additional tax cannot be omitted."
                ),
            ),
            Self::Credits => (
                "ISSUE_ESTATE_K1_CREDITS",
                crate::fixture_english!(
                    "Schedule K-1 (1041) box 13 codes C through T and ZZ, credits and credit recapture (Form 3800 and the credit forms), are not calculated."
                ),
            ),
            Self::OtherInformation => (
                "ISSUE_ESTATE_K1_OTHER_INFORMATION",
                crate::fixture_english!(
                    "Unclassified Schedule K-1 (1041) box 14 information needs the fiduciary's actual income, tax and return treatment before a complete federal estimate. Identified credit, deduction or exclusion benefits have separate categories."
                ),
            ),
            Self::ForeignTaxes
            | Self::Rehabilitation
            | Self::EnergyProperty
            | Self::InvestmentIncome
            | Self::ForeignTradingGrossReceipts
            | Self::AdvancedCoalGasification
            | Self::AdvancedEnergy
            | Self::AdvancedManufacturing
            | Self::CleanElectricity => return None,
        })
    }
}

impl FederalEstateTrustPortfolioK1 {
    pub(crate) fn business_net(&self) -> i64 {
        self.activities
            .activities
            .iter()
            .filter(|a| a.kind == crate::EstateActivityKind::Business)
            .map(|a| a.net(false))
            .sum()
    }
    pub(crate) fn rental_net(&self) -> i64 {
        self.activities
            .activities
            .iter()
            .filter(|a| a.kind != crate::EstateActivityKind::Business)
            .map(|a| a.net(false))
            .sum()
    }
    pub(crate) fn activity_net(&self) -> i64 {
        self.business_net() + self.rental_net()
    }
    pub(crate) fn has_activity_boxes(&self) -> bool {
        !self.activities.activities.is_empty()
    }
}

/// Final estate/trust NOL history succeeded to by a beneficiary
/// Keep every original loss year and separate regular/AMT balances. This is not the beneficiary's own prior-return history.
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
pub struct FinalEstateTrustNol {
    /// Date the estate or trust terminated
    /// Copy the final fiduciary statement's actual termination date when supplied. The first beneficiary carry year is the calendar year containing this date.
    /// [NullText]
    /// The fiduciary's termination date is unavailable
    /// [SetText]
    /// The estate or trust terminated on
    #[libertas_date_only]
    // Tax structure: this date or year belongs to the stated current or retained-return period.
    #[libertas_number(min = 20260101, max = 20261231)]
    pub terminated_on: Option<u32>,
    /// Original estate/trust loss years
    /// Enter one record per actual original tax period from the fiduciary's complete successor statement. Distinct short years can begin in the same calendar year. Order does not change loss use.
    #[libertas_size(min = 1)]
    pub years: Vec<FinalEstateTrustNolYear>,
    /// The fiduciary's statement establishes every original loss year and both remaining balances
    /// Confirm completed prior carrybacks, no special AMT exception, no NII source or section 461 component, and no duplicate excess deduction on termination. Check the fiduciary’s completed successor statement and prior carryback records. No leaves this loss out of this estimate.
    pub fiduciary_history_complete: bool,
    /// Actual fiduciary taxable periods, from the earliest entered loss through termination
    /// Copy consecutive periods from the fiduciary records, including every short year and its final year. A change stub of six days or less on a change to or from a 52/53-week year belongs to the following taxable-period row, not another year. For a following ordinary year, retain its normal month-first beginning separately. Leave the list empty if unavailable; older inherited loss benefits then remain uncomputed. Do not enter beneficiary tax years here.
    pub taxable_periods: Vec<FinalEstateTrustTaxPeriod>,
}

/// Original estate/trust loss year allocated to this beneficiary
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
pub struct FinalEstateTrustNolYear {
    /// Calendar year in which the original fiduciary loss tax year actually began
    /// Keep the actual original year. The accounting-period source determines any separate 52/53-week effective-date classification; it does not shift this original year.
    // Tax structure: this date or year belongs to the stated current or retained-return period.
    #[libertas_number(min = 1900, max = 2026)]
    pub year: u32,
    /// Actual original fiduciary tax year
    /// Copy the beginning and ending dates from the loss-year fiduciary return or successor statement. These dates distinguish short tax years and establish original-year order when losses from different sources share a calendar year. Choose “The original fiduciary tax-period dates are unavailable” when the dates are unknown; do not substitute termination dates or an expiration year.
    /// [NullText]
    /// The original fiduciary tax-period dates are unavailable
    /// [SetText]
    /// The original fiduciary tax period is
    pub original_period: Option<FinalEstateTrustLossPeriod>,
    /// Beneficiary carry years remaining, including 2026
    /// For a loss from a tax year beginning before 2018, copy the remaining carry period from the fiduciary's successor statement after its final tax year. Its final year and your first year each count, including short tax years. Choose “No remaining carry-year count is supplied for this loss” for a loss from 2018 or later. An unknown older period leaves that year's loss benefit out.
    /// [NullText]
    /// No remaining carry-year count is supplied for this loss
    /// [SetText]
    /// The beneficiary carry years remaining, including 2026, are
    // Tax structure: this pre-2018 NOL has a twenty-year carryforward period.
    #[libertas_number(min = 1, max = 20)]
    pub remaining_years: Option<u32>,
    /// Box 11 code E remaining regular NOL allocated to this beneficiary
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub regular_balance: i64,
    /// Box 11 code F remaining AMT NOL allocated to this beneficiary
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub alternative_balance: i64,
}

/// Actual fiduciary taxable-period dates
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
pub struct FinalEstateTrustLossPeriod {
    /// Tax year began
    #[libertas_date_only]
    // Tax structure: this date or year belongs to the stated current or retained-return period.
    #[libertas_number(min = 19000101, max = 20271231)]
    pub began: u32,
    /// Tax year ended
    #[libertas_date_only]
    // Tax structure: this date or year belongs to the stated current or retained-return period.
    #[libertas_number(min = 19000101, max = 20271231)]
    pub ended: u32,
}
/// Accounting basis of one actual fiduciary taxable period
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
pub enum FinalEstateTrustAccountingYear {
    /// Calendar, fiscal or ordinary short tax year
    CalendarFiscalOrShort,
    /// Elected 52/53-week tax year, including its first or final short year
    /// Copy the normal annual boundaries and reference month-end from the fiduciary accounting election/returns. The actual period may be shortened by creation or termination; a change stub of at most six days may precede the normal beginning and is not another taxable year.
    Weeks52Or53 {
        /// Normal annual beginning, before any first-year shortening or appended change stub
        #[libertas_date_only]
        // Tax structure: this date or year belongs to the stated current or retained-return period.
        #[libertas_number(min = 18990101, max = 20261231)]
        annual_began: u32,
        /// Normal annual ending, before any final-year termination
        #[libertas_date_only]
        // Tax structure: this date or year belongs to the stated current or retained-return period.
        #[libertas_number(min = 19000101, max = 20271231)]
        annual_ended: u32,
        /// Last calendar day of the election's reference closing month
        #[libertas_date_only]
        // Tax structure: this date or year belongs to the stated current or retained-return period.
        #[libertas_number(min = 19000101, max = 20271231)]
        reference_ended: u32,
        /// Election's annual closing convention
        closing: FinalEstateTrustWeekClosing,
    },
    /// Ordinary year following an approved change from a 52/53-week year
    /// The change stub of one through six days is part of this one taxable period. Copy its normal ordinary beginning and keep the actual combined dates unchanged.
    CalendarFiscalAfterWeeks52Or53 {
        /// Normal ordinary beginning, after the appended change stub
        #[libertas_date_only]
        // Tax structure: this date or year belongs to the stated current or retained-return period.
        #[libertas_number(min = 19000101, max = 20271231)]
        annual_began: u32,
    },
}

/// How the elected weekday relates to the reference month-end
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
pub enum FinalEstateTrustWeekClosing {
    /// Last occurrence of that weekday in the reference month
    Last,
    /// Occurrence of that weekday nearest the reference month-end
    Nearest,
}

/// One actual fiduciary taxable period and its accounting convention
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
pub struct FinalEstateTrustTaxPeriod {
    /// Actual period on the fiduciary return, including an appended change stub
    pub period: FinalEstateTrustLossPeriod,
    /// Actual accounting convention for this period
    pub accounting: FinalEstateTrustAccountingYear,
}
impl FinalEstateTrustTaxPeriod {
    pub(crate) fn issue(&self) -> Option<crate::validation::ValidationIssue> {
        let issue = |field| {
            crate::validation::ValidationIssue::new("ESTATE_NOL_PERIOD_INVALID").at_field(field)
        };
        if let Some(issue) = self.period.issue() {
            return Some(issue.in_field("period"));
        }
        let p = &self.period;
        match &self.accounting {
            FinalEstateTrustAccountingYear::CalendarFiscalOrShort => {
                let (by, bm, bd) = (p.began / 10000, p.began / 100 % 100, p.began % 100);
                let (ey, em, ed) = (p.ended / 10000, p.ended / 100 % 100, p.ended % 100);
                (!(ey == by || (ey == by + 1 && (em, ed) < (bm, bd))))
                    .then(|| issue("ended").in_field("period"))
            }
            FinalEstateTrustAccountingYear::CalendarFiscalAfterWeeks52Or53 { annual_began } => {
                if !crate::federal_rules::valid_date(*annual_began)
                    || !(19000101..=20271231).contains(annual_began)
                    || annual_began % 100 != 1
                {
                    Some(issue("annual_began").in_field("accounting"))
                } else if !(1..=6).contains(&crate::dates::days_between(p.began, *annual_began)) {
                    Some(issue("began").in_field("period"))
                } else if p.ended < *annual_began || p.ended >= (*annual_began + 10000) {
                    Some(issue("ended").in_field("period"))
                } else {
                    None
                }
            }
            FinalEstateTrustAccountingYear::Weeks52Or53 {
                annual_began,
                annual_ended,
                reference_ended,
                closing,
            } => {
                for (field, date, minimum, maximum) in [
                    ("annual_began", *annual_began, 18990101, 20261231),
                    ("annual_ended", *annual_ended, 19000101, 20271231),
                    ("reference_ended", *reference_ended, 19000101, 20271231),
                ] {
                    if !crate::federal_rules::valid_date(date)
                        || !(minimum..=maximum).contains(&date)
                    {
                        return Some(issue(field).in_field("accounting"));
                    }
                }
                let length = crate::dates::days_between(*annual_began, *annual_ended);
                let before = crate::dates::days_between(*annual_began, p.began);
                let close = crate::dates::days_between(*reference_ended, *annual_ended);
                let prior_reference = crate::dates::last_day_of_month(
                    reference_ended / 10000 - 1,
                    reference_ended / 100 % 100,
                );
                // Keep the existing normal annual and prior closing convention owner.
                let prior_close = crate::dates::days_between(prior_reference, *annual_began) - 1;
                if !matches!(length, 363 | 370) {
                    return Some(issue("annual_ended").in_field("accounting"));
                }
                if before < -6 || p.began > *annual_ended {
                    return Some(issue("began").in_field("period"));
                }
                if p.ended > *annual_ended {
                    return Some(issue("ended").in_field("period"));
                }
                if *reference_ended
                    != crate::dates::last_day_of_month(
                        *reference_ended / 10000,
                        *reference_ended / 100 % 100,
                    )
                {
                    return Some(issue("reference_ended").in_field("accounting"));
                }
                let closing_range = match closing {
                    FinalEstateTrustWeekClosing::Last => -6..=0,
                    FinalEstateTrustWeekClosing::Nearest => -3..=3,
                };
                if !closing_range.contains(&close) {
                    Some(issue("annual_ended").in_field("accounting"))
                } else if !closing_range.contains(&prior_close) {
                    Some(issue("annual_began").in_field("accounting"))
                } else {
                    None
                }
            }
        }
    }
    // Reg1.441-2(c)(1): effective-date laws use the nearest month-first,
    // including the retained actual first day of a first/last shortened year.
    pub(crate) fn effective_year(&self) -> u32 {
        let p = &self.period;
        if !matches!(self.accounting, FinalEstateTrustAccountingYear::Weeks52Or53 { .. }) {
            return p.began / 10000;
        }
        let (year, month) = (p.began / 10000, p.began / 100 % 100);
        let first = year * 10000 + month * 100 + 1;
        let next = if month == 12 { (year + 1) * 10000 + 101 } else { first + 100 };
        if crate::dates::days_between(first, p.began) <= crate::dates::days_between(p.began, next) {
            year
        } else {
            next / 10000
        }
    }
}
impl FinalEstateTrustLossPeriod {
    pub(crate) fn issue(&self) -> Option<crate::validation::ValidationIssue> {
        let issue = |field| {
            crate::validation::ValidationIssue::new("ESTATE_NOL_PERIOD_INVALID").at_field(field)
        };
        if !crate::federal_rules::valid_date(self.began)
            || !(19000101..=20271231).contains(&self.began)
        {
            Some(issue("began"))
        } else if !crate::federal_rules::valid_date(self.ended)
            || !(self.began..=20271231).contains(&self.ended)
        {
            Some(issue("ended"))
        } else {
            None
        }
    }
}
impl FinalEstateTrustNol {
    pub(crate) fn post_2017(
        loss: &FinalEstateTrustNolYear,
        periods: &[FinalEstateTrustTaxPeriod],
    ) -> Option<bool> {
        if periods.is_empty() {
            return (loss.year >= 2018).then_some(true);
        }
        periods
            .iter()
            .find(|p| Some(&p.period) == loss.original_period.as_ref())
            .map(|p| p.effective_year() >= 2018)
    }
    pub(crate) fn rule(&self) -> Option<&'static str> {
        self.issue().map(|issue| issue.key)
    }
    pub(crate) fn issue(&self) -> Option<crate::validation::ValidationIssue> {
        let issue = |field| {
            crate::validation::ValidationIssue::new("ESTATE_NOL_PERIOD_INVALID").at_field(field)
        };
        if self.terminated_on.is_some_and(|date| {
            !crate::federal_rules::valid_date(date) || !(20260101..=20261231).contains(&date)
        }) {
            return Some(issue("terminated_on"));
        }
        for (index, p) in self.taxable_periods.iter().enumerate() {
            if let Some(issue) = p.issue() {
                return Some(issue.in_list("taxable_periods", index));
            }
            if p.period.ended > 20261231 {
                return Some(issue("ended").in_field("period").in_list("taxable_periods", index));
            }
        }
        let mut periods: Vec<_> = self.taxable_periods.iter().enumerate().collect();
        periods.sort_by_key(|(_, p)| p.period.began);
        if !periods.is_empty() {
            if periods.last().map(|(_, p)| p.period.ended) != self.terminated_on {
                return Some(issue("terminated_on"));
            }
            if let Some(pair) = periods.windows(2).find(|pair| {
                crate::dates::days_between(pair[0].1.period.ended, pair[1].1.period.began) != 1
            }) {
                return Some(
                    issue("began").in_field("period").in_list("taxable_periods", pair[1].0),
                );
            }
        }
        for (index, loss) in self.years.iter().enumerate() {
            let loss_issue = |field| issue(field).in_list("years", index);
            if !(1900..=2026).contains(&loss.year) {
                return Some(loss_issue("year"));
            }
            if let Some(period) = &loss.original_period {
                if let Some(issue) = period.issue() {
                    return Some(issue.in_field("original_period").in_list("years", index));
                }
                if period.ended > 20261231
                    || self.terminated_on.is_some_and(|date| period.ended > date)
                {
                    return Some(
                        issue("ended").in_field("original_period").in_list("years", index),
                    );
                }
                if period.began / 10000 != loss.year {
                    return Some(
                        issue("began").in_field("original_period").in_list("years", index),
                    );
                }
            }
            if loss.remaining_years.is_some_and(|years| {
                !(1..=20).contains(&years)
                    || Self::post_2017(loss, &self.taxable_periods) == Some(true)
            }) {
                return Some(loss_issue("remaining_years"));
            }
            if !periods.is_empty() {
                let Some(position) = periods
                    .iter()
                    .position(|(_, p)| Some(&p.period) == loss.original_period.as_ref())
                else {
                    return Some(loss_issue("original_period"));
                };
                if loss
                    .remaining_years
                    .is_some_and(|n| n as i64 != 20 - (periods.len() - position - 1) as i64)
                {
                    return Some(loss_issue("remaining_years"));
                }
            }
            if loss.regular_balance == 0 && loss.alternative_balance == 0 {
                return Some(
                    crate::validation::ValidationIssue::new("NOL_NOTHING_ENTERED")
                        .at_field("regular_balance")
                        .in_list("years", index),
                );
            }
            for prior in &self.years[..index] {
                if prior.year == loss.year
                    && (prior.original_period.is_none()
                        || loss.original_period.is_none()
                        || prior.original_period.as_ref().map(|p| p.began)
                            == loss.original_period.as_ref().map(|p| p.began))
                {
                    return Some(
                        crate::validation::ValidationIssue::new("NOL_YEAR_TWICE")
                            .at_field("year")
                            .in_list("years", index),
                    );
                }
                if let (Some(a), Some(b)) = (&prior.original_period, &loss.original_period)
                    && a.began <= b.ended
                    && b.began <= a.ended
                {
                    return Some(
                        issue("began").in_field("original_period").in_list("years", index),
                    );
                }
            }
        }
        None
    }
    pub(crate) fn valid(&self) -> bool {
        self.rule().is_none()
            && !self.years.is_empty()
            && self.years.iter().all(|loss| {
                // Arithmetic safety: the source-confirmation summary still sums
                // this statement's cents natively. Nonoverlapping original
                // periods within 1900..2026 plus these scalar bounds protect it;
                // pooled cross-statement carriers use exact arithmetic.
                (0..=100_000_000_000).contains(&loss.regular_balance)
                    && (0..=100_000_000_000).contains(&loss.alternative_balance)
            })
    }
}

/// Estate or trust box 14 code H adjustment for the beneficiary
/// Form 8960 line 7 is separate from the income boxes. A positive amount also increases modified AGI by the same amount; for a negative amount use the fiduciary's statement to determine whether any part changes modified AGI.
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
pub struct EstateTrustNiitAdjustment {
    /// Form 8960 line 7 change to net investment income
    /// Positive or negative as shown in the fiduciary's box 14 code H statement. Do not duplicate interest, dividends, gains or royalties already entered above.
    #[libertas_llm_doc_field(allow_empty = false)]
    #[libertas_money("USD", 2)]
    pub line_7: i64,
    /// Change to Form 8960 modified adjusted gross income
    /// For a positive line 7 amount, repeat that amount here. For a negative line 7 amount, enter the signed part that the fiduciary identifies as also changing modified AGI; enter zero only when none does.
    #[libertas_llm_doc_field(allow_empty = false)]
    #[libertas_money("USD", 2)]
    pub modified_agi: i64,
}

impl EstateTrustNiitAdjustment {
    pub(crate) fn valid(&self) -> bool {
        (-100_000_000_000..=100_000_000_000).contains(&self.line_7)
            && (-100_000_000_000..=100_000_000_000).contains(&self.modified_agi)
            && if self.line_7 > 0 {
                self.modified_agi == self.line_7
            } else {
                self.modified_agi.unsigned_abs() <= self.line_7.unsigned_abs()
            }
    }
}

/// Qualified wildfire relief payment received in 2026
/// Section 139M excludes only uncompensated losses, expenses or damages from a federally declared forest or range fire. A partially qualifying payment needs separate taxable-source treatment.
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
#[libertas_llm_doc_trans(
    instruction = "Read one Form 1099-MISC reporting this wildfire relief payment exactly. Check the form's tax year against the supplied year and report a mismatch as an error. Read box 3 other income; report an error when box 3 is blank. Read box 4 federal income tax withheld, returning an empty string when it is clearly blank. Report an illegible amount, or two values that conflict, as an error. Do not read any other box. Do not report the fire, its declaration, the dates or whether the payment qualifies; the filer answers those. The file may hold several copies of this form, such as Copy B and Copy 2; copies of the same form are one form.",
    validation = "$.document_facts",
    doc_type = "application/pdf,image/*"
)]
pub struct FederalWildfireRelief {
    /// Date payment was received in 2026
    #[libertas_date_only]
    pub paid: u32,
    /// Federal forest or range-fire disaster declaration date
    /// The declaration must be after December 31, 2014 and before January 1, 2027.
    #[libertas_date_only]
    pub declared: u32,
    /// Federal disaster declaration reference
    #[libertas_size(min = 1)]
    pub reference: String,
    /// Qualified payment received, excluding any separately taxable component
    #[libertas_llm_doc_field(allow_empty = false)]
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 1)]
    pub amount: i64,
    /// Federal tax actually withheld on a Form 1099 reporting this payment
    /// Enter zero if no Form 1099 withheld tax; a regular employer wage payment is not qualified wildfire relief.
    #[libertas_llm_doc_field]
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    #[libertas_default(0)]
    pub withholding: i64,
    /// This entire payment meets section 139M and has no duplicate tax benefit
    /// Confirm a federally declared forest or range fire, payment to or for this individual for resulting uncompensated losses, expenses or damages, and no overlap with insurance or other compensation. Employer-paid wages that would otherwise have been paid are excluded from this entry. Do not also enter the payment as wages or other income; do not claim a deduction or credit for a compensated expense or increase property basis by the excluded amount. Separate any nonqualifying portion into its proper taxable income source. No taxes the payment as other income.
    /// Check the payer statement, disaster declaration and reimbursed-expense records.
    pub qualified: bool,
}
impl FederalWildfireRelief {
    // What the payment adds to income: nothing when it qualifies as excluded.
    pub(crate) fn on_return(&self) -> i64 {
        if self.qualified { 0 } else { self.amount }
    }
    // The page's client rules, repeated on save (the server twins).
    pub(crate) fn issue(&self) -> Option<crate::validation::ValidationIssue> {
        if !(20260101..=20261231).contains(&self.paid) {
            Some(
                crate::validation::ValidationIssue::new("RELIEF_RECEIVED_OUTSIDE_2026")
                    .at_field("paid"),
            )
        } else if !(20150101..=20261231).contains(&self.declared) {
            Some(
                crate::validation::ValidationIssue::new("WILDFIRE_DECLARED_OUTSIDE_2015_2026")
                    .at_field("declared"),
            )
        } else if self.withholding > self.amount {
            Some(
                crate::validation::ValidationIssue::new("RELIEF_WITHHOLDING_ABOVE_PAYMENT")
                    .at_field("withholding"),
            )
        } else {
            None
        }
    }
    pub(crate) fn valid(&self) -> bool {
        (20260101..=20261231).contains(&self.paid)
            && crate::federal_rules::valid_date(self.paid)
            && (20150101..=20261231).contains(&self.declared)
            && crate::federal_rules::valid_date(self.declared)
            && !self.reference.trim().is_empty()
            && (1..=100_000_000_000).contains(&self.amount)
            && (0..=self.amount).contains(&self.withholding)
    }
}

/// Purpose of a section 139 qualified disaster relief payment
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
pub enum DisasterReliefPurpose {
    /// Reasonable and necessary personal, family, living or funeral expense
    PersonalExpense,
    /// Reasonable and necessary repair of a personal residence or its contents
    ResidenceOrContents,
    /// Government payment to promote the general welfare after the disaster
    GovernmentWelfare,
    /// Common carrier's payment because a disaster caused death or physical injury
    CommonCarrier {
        /// Transportation common carrier that made the payment
        #[libertas_size(min = 1)]
        carrier: String,
        /// Death or physical injury caused by the disaster
        loss: DisasterCarrierLoss,
    },
}
/// Harm compensated by a common carrier under section 139(b)(3)
#[derive(
    Clone, Copy, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport,
)]
pub enum DisasterCarrierLoss {
    /// Death caused by the disaster
    Death,
    /// Personal physical injury caused by the disaster
    PhysicalInjury,
}
/// Section 692(c)(2) event type used by section 139(c)(1)
#[derive(
    Clone, Copy, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport,
)]
pub enum DisasterActionKind {
    /// Terroristic activity directed against the United States or an ally
    Terrorism,
    /// U.S. Armed Forces action responding to violence or aggression against the United States or an ally, excluding training
    Military,
}
impl DisasterReliefPurpose {
    fn valid(&self) -> bool {
        self.issue().is_none()
    }
    fn issue(&self) -> Option<crate::validation::ValidationIssue> {
        match self {
            Self::CommonCarrier { carrier, .. } if carrier.trim().is_empty() => Some(
                crate::validation::ValidationIssue::new("DISASTER_SOURCE_TEXT_INVALID")
                    .at_field("carrier")
                    .in_field("purpose"),
            ),
            _ => None,
        }
    }
}

/// Why the event is a qualified disaster under section 139(c)
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
pub enum DisasterQualification {
    /// Terroristic or military action under section 692(c)(2)
    TerrorOrMilitary {
        /// Type of qualifying action
        kind: DisasterActionKind,
        /// Event and supporting determination or evidence
        #[libertas_size(min = 1)]
        event: String,
    },
    /// Federally declared disaster under section 139(c)(2)
    FederalDeclaration {
        /// Federal disaster declaration reference
        #[libertas_size(min = 1)]
        reference: String,
    },
    /// Accident involving a transportation common carrier under section 139(c)(3)
    CarrierAccident {
        /// Qualifying accident or disaster reference
        #[libertas_size(min = 1)]
        event: String,
    },
    /// Other event determined catastrophic by the Treasury Secretary under section 139(c)(3)
    SecretaryCatastrophe {
        /// Secretary's determination or IRS notice identifying the event
        #[libertas_size(min = 1)]
        determination: String,
    },
    /// Government assistance after an applicable authority determined the disaster warrants aid under section 139(c)(4)
    /// This basis applies only to a government general-welfare payment, not a private payment for personal or residence expenses.
    GovernmentAssistance {
        /// Event or disaster reference
        #[libertas_size(min = 1)]
        event: String,
        /// Federal, state or local authority that determined aid was warranted
        #[libertas_size(min = 1)]
        authority: String,
        /// Federal, state or local government agency that paid the assistance
        #[libertas_size(min = 1)]
        payer: String,
    },
}
impl DisasterQualification {
    pub(crate) fn valid(&self, purpose: &DisasterReliefPurpose) -> bool {
        self.issue(purpose).is_none()
    }
    fn issue(&self, purpose: &DisasterReliefPurpose) -> Option<crate::validation::ValidationIssue> {
        self.binding_issue(purpose).or_else(|| self.text_issue())
    }
    fn binding_issue(
        &self,
        purpose: &DisasterReliefPurpose,
    ) -> Option<crate::validation::ValidationIssue> {
        match self {
            Self::CarrierAccident { .. }
                if !matches!(purpose, DisasterReliefPurpose::CommonCarrier { .. }) =>
            {
                Some(
                    crate::validation::ValidationIssue::new(
                        "DISASTER_CARRIER_ACCIDENT_NEEDS_CARRIER_PAYMENT",
                    )
                    .at_field("purpose"),
                )
            }
            Self::GovernmentAssistance { .. }
                if !matches!(purpose, DisasterReliefPurpose::GovernmentWelfare) =>
            {
                Some(
                    crate::validation::ValidationIssue::new(
                        "DISASTER_ASSISTANCE_NEEDS_GOVERNMENT_PAYMENT",
                    )
                    .at_field("purpose"),
                )
            }
            _ => None,
        }
    }
    fn text_issue(&self) -> Option<crate::validation::ValidationIssue> {
        let named = |value: &str, field| {
            value.trim().is_empty().then(|| {
                crate::validation::ValidationIssue::new("DISASTER_SOURCE_TEXT_INVALID")
                    .at_field(field)
                    .in_field("qualification")
            })
        };
        match self {
            Self::TerrorOrMilitary { event, .. } | Self::CarrierAccident { event } => {
                named(event, "event")
            }
            Self::FederalDeclaration { reference } => named(reference, "reference"),
            Self::SecretaryCatastrophe { determination } => named(determination, "determination"),
            Self::GovernmentAssistance { event, authority, payer } => named(event, "event")
                .or_else(|| named(authority, "authority"))
                .or_else(|| named(payer, "payer")),
        }
    }
}

/// Qualified disaster relief payment received in 2026
/// Section 139 excludes eligible individual assistance after a qualified disaster. Use a separate income source for any taxable portion or for a payment with a different tax treatment. If a Form 1099-G box 6 shows this grant, enter it here and leave it out of that 1099-G's box 6.
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
#[libertas_llm_doc_trans(
    instruction = "Read one Form 1099-MISC or Form 1099-G reporting this disaster relief payment exactly. Check the form's tax year against the supplied year and report a mismatch as an error. For a 1099-MISC read box 3 other income; for a 1099-G read box 6 taxable grants; report an error when that box is blank. Read box 4 federal income tax withheld, returning an empty string when it is clearly blank. Report an illegible amount, or two values that conflict, as an error. Do not read any other box. Do not report the disaster, its basis, what the payment covered or whether it qualifies; the filer answers those. The file may hold several copies of this form, such as Copy B and Copy 2; copies of the same form are one form.",
    validation = "$.document_facts",
    doc_type = "application/pdf,image/*"
)]
pub struct FederalDisasterRelief {
    /// Date the payment was received in 2026
    #[libertas_date_only]
    pub received: u32,
    /// Qualified-disaster basis
    pub qualification: DisasterQualification,
    /// What the qualified payment covered
    pub purpose: DisasterReliefPurpose,
    /// Entire eligible payment; enter any taxable component separately
    #[libertas_llm_doc_field(allow_empty = false)]
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 1)]
    pub amount: i64,
    /// Actual federal income tax withheld on a payer's Form 1099, if any
    /// Section 139 relief is excluded even when a payer reports it as Form 1099 income. Enter zero when no tax was withheld; claim only the tax actually withheld, not a hypothetical amount.
    #[libertas_llm_doc_field]
    #[libertas_default(0)]
    #[libertas_money("USD", 2)]
    #[libertas_number(min = 0)]
    pub withholding: i64,
    /// This entire payment qualifies under section 139
    /// Confirm the selected qualified-disaster basis and payment purpose, payment to or for this individual, and no insurance or other payment for the same compensated expense. Terrorism must target the United States or an ally; military action must involve U.S. forces responding to violence or aggression against the United States or an ally and cannot be training. A Secretary-catastrophe basis needs an actual Treasury or IRS determination. A common-carrier payment must come from the named transportation carrier because the disaster caused death or personal physical injury; an accident involving that carrier can itself be the qualifying disaster. A nonfederal government-assistance basis requires an applicable authority's determination and a government welfare payment; it cannot support a private expense reimbursement. The payment is not wage or business-income replacement or compensation for services. A government-welfare payment came from a federal, state or local government or its agency and served individual or family needs. Do not enter this amount elsewhere as taxable income or claim a deduction or credit for a compensated expense; account for any property-loss reimbursement separately. No taxes the payment as other income.
    /// Check the payer statement, disaster declaration and reimbursed-expense records.
    pub qualified: bool,
}
impl FederalDisasterRelief {
    // What the payment adds to income: nothing when it qualifies as excluded.
    pub(crate) fn on_return(&self) -> i64 {
        if self.qualified { 0 } else { self.amount }
    }
    // The page's client rules, repeated on save (the server twins).
    pub(crate) fn issue(&self) -> Option<crate::validation::ValidationIssue> {
        if !(20260101..=20261231).contains(&self.received) {
            Some(
                crate::validation::ValidationIssue::new("RELIEF_RECEIVED_OUTSIDE_2026")
                    .at_field("received"),
            )
        } else if self.withholding > self.amount {
            Some(
                crate::validation::ValidationIssue::new("RELIEF_WITHHOLDING_ABOVE_PAYMENT")
                    .at_field("withholding"),
            )
        } else {
            self.qualification
                .binding_issue(&self.purpose)
                .or_else(|| self.purpose.issue())
                .or_else(|| self.qualification.text_issue())
        }
    }

    pub(crate) fn valid(&self) -> bool {
        (20260101..=20261231).contains(&self.received)
            && crate::federal_rules::valid_date(self.received)
            && self.purpose.valid()
            && self.qualification.valid(&self.purpose)
            && (1..=100_000_000_000).contains(&self.amount)
            && (0..=self.amount).contains(&self.withholding)
    }
}

