impl Form2439 {
    // The first relationship between this page's fields that fails, by its
    // rule's key, in the order of the client rules.
    pub(crate) fn issue(&self) -> Option<crate::validation::ValidationIssue> {
        if i128::from(self.unrecaptured)
            + i128::from(self.small_business)
            + i128::from(self.collectibles)
            > i128::from(self.gain)
        {
            return Some(
                crate::validation::ValidationIssue::new("FORM_2439_PARTS_ABOVE_1A")
                    .at_field("gain"),
            );
        }
        if self.tax_paid > self.gain {
            return Some(
                crate::validation::ValidationIssue::new("FORM_2439_TAX_ABOVE_1A")
                    .at_field("tax_paid"),
            );
        }
        (self.small_business != 0 && self.section_1202_exclusion.is_none()).then(|| {
            crate::validation::ValidationIssue::new("FORM_2439_SECTION_1202_NEEDS_EXCLUSION")
                .at_field("section_1202_exclusion")
        })
    }
    // The stored statement this page writes.
    pub(crate) fn record(&self) -> UndistributedGain {
        UndistributedGain {
            gain: self.gain,
            unrecaptured: self.unrecaptured,
            small_business: self.small_business,
            section_1202_exclusion: self.section_1202_exclusion,
            collectibles: self.collectibles,
            tax_paid: self.tax_paid,
            special: self.special,
        }
    }
    // The label: the fund as typed.
    pub(crate) fn label(&self) -> String {
        self.fund.clone()
    }
}

