/// Form 1098-E
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
#[libertas_llm_doc_trans(
    instruction = "Read this one Form 1098-E (Student Loan Interest Statement) exactly. Check its calendar year against the supplied year; report a mismatch. Read box 1 student loan interest received by the lender as printed; a blank, illegible or conflicting box 1 is an error, never zero or a guess. Do not read box 2; the filer answers it and figures any additional interest. Do not infer whether the filer is legally obligated to repay the loan or any fact absent from the form. The file may hold several copies of this form, such as Copy B and Copy C; copies of the same form are one form.",
    validation = "$.document_facts",
    doc_type = "application/pdf,image/*"
)]
pub struct Form1098E {
    /// Box 1 student loan interest received by lender
    #[libertas_llm_doc_field(allow_empty = false)]
    #[libertas_money("USD", 2)]
    // Excluded from widening: student_loan_candidate calls the i64 qualified_interest receiver before native source validation; a checked receiver is required.
    #[libertas_number(min = 0, max = 100000000000)]
    pub interest: i64,
    /// Box 2 checked
    #[libertas_default(NotChecked)]
    pub box_2: Form1098EBox2,
}
impl Form1098E {
    /// Box 1 plus the qualified interest the filer figured for a checked box 2.
    pub(crate) fn qualified_interest(&self) -> i64 {
        self.interest
            + match self.box_2 {
                Form1098EBox2::NotChecked => 0,
                Form1098EBox2::Checked { additional_interest } => additional_interest,
            }
    }
    pub(crate) fn valid(&self) -> bool {
        (0..=100000000000).contains(&self.interest)
            && match self.box_2 {
                Form1098EBox2::NotChecked => true,
                Form1098EBox2::Checked { additional_interest } => {
                    (0..=100000000000).contains(&additional_interest)
                }
            }
    }
}
/// Box 2 checked
/// The lender checks box 2 when box 1 leaves out loan origination fees or capitalized interest on a loan made before September 1, 2004.
#[derive(Clone, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport)]
#[libertas_inline_choices]
pub enum Form1098EBox2 {
    /// Not checked
    NotChecked,
    /// Checked
    Checked {
        /// Additional qualified interest you figured (origination fees and capitalized interest paid in 2026)
        /// Spread each loan origination fee charged for the use of money over the loan's term and include the part for the months you made payments in 2026. Include capitalized interest to the extent your 2026 payments of principal paid it off: a payment applies first to unpaid stated interest, then to the origination fee, then to capitalized interest, then to principal. See Publication 970, Student Loan Interest Deduction, for a worked example. Enter zero if none.
        #[libertas_money("USD", 2)]
        // Excluded from widening: student_loan_candidate calls the i64 qualified_interest receiver before native source validation; a checked receiver is required.
        #[libertas_number(min = 0, max = 100000000000)]
        #[libertas_default(0)]
        additional_interest: i64,
    },
}

