/// Credit situation
/// The refusal kinds of More credits as stored: payload-less, so the persisted
/// return carries no page item (a page item's choices of businesses and sales
/// are an EnumSource of the request and cannot be stored).
#[derive(
    Clone, Copy, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport,
)]
pub enum MoreCreditRefusal {
    /// A selected credit without a 2026 form line, retained for its left-out notice
    OtherCredit,
}

impl From<MoreCreditRefusal> for MoreCredit {
    fn from(kind: MoreCreditRefusal) -> Self {
        match kind {
            MoreCreditRefusal::OtherCredit => Self::OtherCredit,
        }
    }
}

impl MoreCredit {
    // The stored form of a refusal kind.
    pub(crate) fn refusal(&self) -> Option<MoreCreditRefusal> {
        Some(match self {
            Self::OtherCredit => MoreCreditRefusal::OtherCredit,
            _ => return None,
        })
    }
}
impl MoreCreditRefusal {
    pub(crate) fn refused(&self) -> Option<crate::federal_rules::Refusal> {
        MoreCredit::from(*self).refused()
    }
}

