impl FederalCredits {
    pub(crate) fn care_expenses(&self) -> i64 {
        self.care.filer_expenses()
    }

    // The one owner of "expenses taken into account for an education credit"
    // (IRC 135(d)(2)(A), 529(c)(3)(B)(v), 530(d)(2)(C)): Form 8863 figures its
    // credits from it, and every benefit that must not reuse those expenses
    // (the savings bond exclusion, the education account distributions) reads
    // it. One element per education entry, in list order, in whole dollars.
    // `credit_allowed` is false when the App allows no credit (married filing
    // separately, a filer another taxpayer claims, no filer with a valid SSN);
    // a dependent student without a valid SSN takes none either. A filer who
    // is the student needs no SSN of their own beyond the filer rule: on a
    // joint return one spouse's SSN suffices even for a spouse-student (2026
    // i8863 "Identification requirement" Tip).
    pub(crate) fn education_expenses_used(
        &self,
        students: &[PersonChoice],
        credit_allowed: bool,
    ) -> Vec<EducationUse> {
        // The lifetime learning credit's per-return cap is shared in list order.
        let mut lifetime_room = crate::year_constants::LIFETIME_LEARNING_EXPENSE_CAP_DOLLARS;
        self.education
            .iter()
            .map(|entry| {
                let student = students.iter().find(|v| v.id == entry.student);
                let method = entry.method();
                let qualified = crate::kernel::ratio::dollars(entry.expenses.qualified(method));
                let used =
                    if !credit_allowed || student.is_some_and(|v| !v.is_filer() && !v.valid_ssn) {
                        0
                    } else if method == EducationMethod::AmericanOpportunity {
                        phase::cap(
                            qualified,
                            [crate::year_constants::AMERICAN_OPPORTUNITY_EXPENSE_CAP_DOLLARS],
                        )
                    } else {
                        let used = phase::cap(qualified, [lifetime_room]);
                        lifetime_room = crate::kernel::carry::native_balance(lifetime_room, used);
                        used
                    };
                // Form 8815 line 2 takes tuition and fees only (i8815 line 2).
                // The credit's consumed expenses are attributed to the
                // course materials first, so the tuition the credit did not
                // need stays available for the exclusion; no rule orders the
                // credit's expenses, and this reading favors the filer.
                let materials = entry.expenses.school_materials
                    + if method == EducationMethod::AmericanOpportunity {
                        entry.expenses.other_materials
                    } else {
                        0
                    };
                let used_tuition =
                    used - phase::cap(used, [crate::kernel::ratio::dollars(materials)]);
                EducationUse {
                    person: student.map(|v| v.id),
                    method,
                    qualified,
                    used,
                    used_tuition,
                }
            })
            .collect()
    }
}

// What one education entry's credit takes into account, in whole dollars.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct EducationUse {
    // The student's person identity; None for an entry naming no catalog student.
    pub(crate) person: Option<i64>,
    pub(crate) method: EducationMethod,
    // The credit's qualified expenses before the credit's own caps.
    pub(crate) qualified: i64,
    // The part the credit consumes: at most $4,000 for the American
    // opportunity credit, and the return's $10,000 for the lifetime learning
    // credit shared in list order; zero when no credit is allowed. Form 1099-Q
    // reads this whole figure (its college costs include course materials).
    pub(crate) used: i64,
    // The part of `used` that falls on tuition and fees: `used` less the
    // course materials (the credit takes the materials first). Form 8815
    // line 2 reads this figure, because that line counts tuition and fees only.
    pub(crate) used_tuition: i64,
}

/// Education credit to evaluate
/// Credit-specific questions belong only to the selected credit.
#[derive(
    Clone, Copy, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport,
)]
pub enum EducationChoice {
    /// American opportunity credit
    /// First four years, fewer than four prior claims, at least half-time degree study, and no disqualifying drug conviction.
    AmericanOpportunity,
    /// Lifetime learning credit
    LifetimeLearning,
}
impl FederalEducation {
    pub(crate) fn method(&self) -> EducationMethod {
        match self.method {
            EducationChoice::AmericanOpportunity => EducationMethod::AmericanOpportunity,
            EducationChoice::LifetimeLearning => EducationMethod::LifetimeLearning,
        }
    }
}

/// When the retirement distribution was received
/// For 2026 the backend uses this return's filing status; other years ask about joint filing.
#[derive(
    Clone, Copy, Debug, PartialEq, Eq, LibertasAvroEncode, LibertasAvroDecode, LibertasExport,
)]
pub enum SaverDistributionPeriod {
    /// 2024
    PriorTwo {
        /// Filed jointly with the current spouse for this year
        /// The filing-status box on the 2024 Form 1040 shows it.
        joint_with_current_spouse: bool,
    },
    /// 2025
    PriorOne {
        /// Filed jointly with the current spouse for this year
        /// The filing-status box on the 2025 Form 1040 shows it.
        joint_with_current_spouse: bool,
    },
    /// 2026
    TaxYear,
    /// 2027, before the 2026 return due date including extensions
    FollowingYear {
        /// Filed or expect to file jointly with the current spouse for this year
        /// Not sure, while the 2027 status is undecided, is treated as joint: the distribution then also reduces the spouse's credit.
        // A future filing decision has no filed return to look up. Retain this
        // conservative unknown with WARN_SAVER_2027_JOINT_ASSUMED.
        joint_with_current_spouse: Answer,
    },
}
impl FederalSaverDistribution {
    pub(crate) fn year(&self) -> SaverDistributionYear {
        match self.year {
            SaverDistributionPeriod::PriorTwo { .. } => SaverDistributionYear::PriorTwo,
            SaverDistributionPeriod::PriorOne { .. } => SaverDistributionYear::PriorOne,
            SaverDistributionPeriod::TaxYear => SaverDistributionYear::TaxYear,
            SaverDistributionPeriod::FollowingYear { .. } => SaverDistributionYear::FollowingYear,
        }
    }
    pub(crate) fn joint_with_current_spouse(&self) -> Answer {
        match self.year {
            SaverDistributionPeriod::PriorTwo { joint_with_current_spouse }
            | SaverDistributionPeriod::PriorOne { joint_with_current_spouse } => {
                crate::common::yes_no(joint_with_current_spouse)
            }
            SaverDistributionPeriod::FollowingYear { joint_with_current_spouse } => {
                joint_with_current_spouse
            }
            SaverDistributionPeriod::TaxYear => Answer::No,
        }
    }
}

